188	    /**
189	     * Phase 2 of the two-phase impersonation flow (M-12).
190	     *
191	     * <p>Atomically consumes the exchange token (Redis single-use enforcement), mints the
192	     * impersonation JWT, and places it in an httpOnly access-token cookie identical to the
193	     * normal login cookie. The impersonation JWT is never returned in the response body —
194	     * it exists only in the cookie jar, inaccessible to JavaScript.</p>
195	     *
196	     * <p>Security controls applied here:
197	     * <ul>
198	     *   <li>{@code @RequiresPermission(revalidate=true)}: verifies SYSTEM_ADMIN from DB,
199	     *       not from cached JWT claims, immediately before consumption.</li>
200	     *   <li>Issuer binding: service verifies the consuming admin matches the token issuer.</li>
201	     *   <li>Single-use: Redis GETDEL atomicity prevents replay.</li>
202	     *   <li>Audit log: full impersonation event written asynchronously.</li>
203	     * </ul></p>
204	     *
205	     * <p>Returns: {@code 204 No Content} on success (no body — the session is in the cookie).
206	     * Returns {@code 403} if the exchange token is invalid, expired, or already used.</p>
207	     */
208	    @PostMapping("/impersonate/consume")
209	    @Operation(summary = "Consume impersonation exchange token (phase 2 of 2)",
210	            description = "Validates and consumes the exchange token from phase 1 (single-use, 60s TTL). " +
211	                    "On success, sets the impersonation JWT as an httpOnly access-token cookie and returns 204. " +
212	                    "The JWT is never present in the response body.")
213	    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)
214	    public ResponseEntity<Void> consumeImpersonationExchangeToken(
215	            @Valid @RequestBody ConsumeImpersonationRequest request,
216	            HttpServletResponse response) {
217	        log.info("SuperAdmin consuming impersonation exchange token");
218	        String impersonationJwt = systemAdminService.consumeImpersonationExchangeToken(
219	                request.getExchangeToken());
220	
221	        // Place the impersonation JWT in the same httpOnly cookie the normal login flow uses.
222	        // The cookie is not readable by JavaScript (HttpOnly). The JwtAuthenticationFilter
223	        // already understands impersonation tokens: it sets SecurityContext + TenantContext
224	        // from the token's tenantId / impersonatorId claims.
225	        response.addHeader(HttpHeaders.SET_COOKIE,
226	                cookieConfig.createAccessTokenCookie(impersonationJwt).toString());
227	        // Also emit the hardened __Host- variant for clients that accept it (S10-J rollover).
228	        response.addHeader(HttpHeaders.SET_COOKIE,
229	                cookieConfig.createHardenedAccessTokenCookie(impersonationJwt).toString());
230	
231	        log.info("Impersonation session established via httpOnly cookie for admin={}",
232	                SecurityContext.getCurrentUserId());
233	        return ResponseEntity.noContent().build();
234	    }
