130	                .collect(Collectors.toList());
131	
132	        if (tenantIds.isEmpty()) {
133	            return tenantsPage.map(t -> mapToTenantListItem(t, 0L, 0L, null));
134	        }
135	
136	        // Batch queries — 2 queries for the whole page instead of 2×N
137	        Map<UUID, Long> employeeCountByTenant = employeeRepository.countByTenantIdIn(tenantIds)
138	                .stream().collect(Collectors.toMap(
139	                        r -> (UUID) r[0],
140	                        r -> (Long) r[1]
141	                ));
142	
143	        Map<UUID, Long> userCountByTenant = userRepository.countByTenantIdIn(tenantIds)
144	                .stream().collect(Collectors.toMap(
145	                        r -> (UUID) r[0],
146	                        r -> (Long) r[1]
147	                ));
148	
149	        // Last-activity lookup: still per-tenant but only for the page slice.
150	        // A tenant with no login history yields a null timestamp; Collectors.toMap
151	        // rejects null values (NPE), so build a null-tolerant map instead.
152	        Map<UUID, LocalDateTime> lastActivityByTenant = new HashMap<>();
153	        for (UUID id : tenantIds) {
154	            lastActivityByTenant.put(id, getLastActivityForTenant(id));
155	        }
156	
157	        return tenantsPage.map(tenant -> mapToTenantListItem(
158	                tenant,
159	                employeeCountByTenant.getOrDefault(tenant.getId(), 0L),
160	                userCountByTenant.getOrDefault(tenant.getId(), 0L),
161	                lastActivityByTenant.get(tenant.getId())
162	        ));
163	    }
