195	    /**
196	     * Phase 1 of the two-phase impersonation flow (M-12).
197	     *
198	     * <p>Generates a short-lived (60s), single-use opaque exchange token stored in Redis.
199	     * The impersonation JWT is NOT minted here and is NOT returned to the caller — it is
200	     * minted only in {@link #consumeImpersonationExchangeToken} and placed directly in
201	     * an httpOnly cookie. This eliminates the prior gap where a 15-min JWT was returned
202	     * to the browser's JS context but never consumed.</p>
203	     *
204	     * @param tenantId the target tenant to impersonate
205	     * @return exchange token metadata (opaque token + TTL + tenant info for UI display)
206	     * @throws ResourceNotFoundException if the tenant does not exist
207	     * @throws IllegalStateException     if the Redis token store is unavailable (fail-closed)
208	     */
209	    @Transactional
210	    public ImpersonationExchangeResponse generateImpersonationExchangeToken(UUID tenantId) {
211	        log.info("SuperAdmin initiating impersonation exchange token generation for tenant: {}", tenantId);
212	
213	        Tenant tenant = tenantRepository.findById(tenantId)
214	                .orElseThrow(() -> new ResourceNotFoundException("Tenant not found with ID: " + tenantId));
215	
216	        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();
217	        // Verify the calling user exists in our DB (defence-in-depth against stale JWT).
218	        userRepository.findById(currentUserId)
219	                .orElseThrow(() -> new ResourceNotFoundException("Issuing admin not found"));
220	
221	        String exchangeToken = impersonationExchangeTokenService.generateExchangeToken(currentUserId, tenantId);
222	
223	        // Audit-log exchange token generation. Full impersonation audit emitted at consume time.
224	        auditLogService.logAction(
225	                "TENANT",
226	                tenantId,
227	                AuditLog.AuditAction.LOGIN,
228	                Map.of("action", "impersonation_exchange_token_generated"),
229	                Map.of("admin_user_id", currentUserId.toString()),
230	                "SuperAdmin generated impersonation exchange token for tenant: " + tenant.getName()
231	        );
232	
233	        return ImpersonationExchangeResponse.builder()
234	                .exchangeToken(exchangeToken)
235	                .tenantId(tenantId.toString())
236	                .tenantName(tenant.getName())
237	                .expiresInSeconds(ImpersonationExchangeTokenService.TTL_SECONDS)
238	                .build();
239	    }
