241	    /**
242	     * Phase 2 of the two-phase impersonation flow (M-12).
243	     *
244	     * <p>Atomically consumes the exchange token from Redis (single-use enforcement),
245	     * mints an impersonation JWT, and returns it so the caller (SystemAdminController)
246	     * can place it in an httpOnly cookie. The JWT never enters a JS-readable context.</p>
247	     *
248	     * <p>Security properties enforced here:
249	     * <ul>
250	     *   <li><strong>Single-use:</strong> Redis GETDEL is atomic — a second call with the same token
251	     *       returns null immediately.</li>
252	     *   <li><strong>Expiry:</strong> Redis TTL (60s) enforced by the store; expired tokens also return
253	     *       null.</li>
254	     *   <li><strong>SuperAdmin-only issuance:</strong> the controller guard ({@code @RequiresPermission}
255	     *       with {@code revalidate=true}) verifies SYSTEM_ADMIN permission from the database.</li>
256	     *   <li><strong>Issuer binding:</strong> the exchange token embeds the admin's user ID; this
257	     *       method verifies the current caller matches the issuer.</li>
258	     *   <li><strong>Audit completeness:</strong> full impersonation event is written to the audit log.</li>
259	     * </ul></p>
260	     *
261	     * @param exchangeToken the opaque token from phase 1
262	     * @return a signed impersonation JWT to be set as an httpOnly cookie by the controller
263	     * @throws BusinessException if the exchange token is invalid, expired, or already used
264	     */
265	    @Transactional
266	    public String consumeImpersonationExchangeToken(String exchangeToken) {
267	        Map<String, UUID> payload = impersonationExchangeTokenService.consumeExchangeToken(exchangeToken);
268	        if (payload == null) {
269	            log.warn("Impersonation consume failed — exchange token not found, expired, or replayed");
270	            throw new BusinessException("Impersonation exchange token is invalid, expired, or already used");
271	        }
272	
273	        UUID adminUserId = payload.get("adminId");
274	        UUID targetTenantId = payload.get("targetTenantId");
275	
276	        Tenant tenant = tenantRepository.findById(targetTenantId)
277	                .orElseThrow(() -> new ResourceNotFoundException("Target tenant not found: " + targetTenantId));
278	
279	        User adminUser = userRepository.findById(adminUserId)
280	                .orElseThrow(() -> new ResourceNotFoundException("Issuing admin user not found: " + adminUserId));
281	
282	        // Issuer binding: verify the current caller is the same admin who generated the token.
283	        // The @RequiresPermission guard already verified SYSTEM_ADMIN; this closes the race
284	        // where Admin-A generates and Admin-B presents the same token.
285	        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();
286	        if (!adminUserId.equals(currentUserId)) {
287	            log.error("SEC: Impersonation exchange token issuer {} does not match caller {}",
288	                    adminUserId, currentUserId);
289	            throw new BusinessException("Exchange token was not issued by the current user");
290	        }
291	
292	        String impersonationJwt = jwtTokenProvider.generateImpersonationToken(
293	                adminUser.getId(),
294	                adminUser.getEmail(),
295	                targetTenantId,
296	                adminUser.getRoles().stream()
297	                        .map(r -> r.getCode())
298	                        .collect(Collectors.toSet())
299	        );
300	
301	        // Full impersonation audit: who impersonated whom, when, from which IP.
302	        auditLogService.logAction(
303	                "TENANT",
304	                targetTenantId,
305	                AuditLog.AuditAction.LOGIN,
306	                Map.of("action", "impersonation_session_started"),
307	                Map.of(
308	                        "admin_user_id", adminUser.getId().toString(),
309	                        "admin_email", adminUser.getEmail(),
310	                        "target_tenant_id", targetTenantId.toString(),
311	                        "target_tenant_name", tenant.getName()
312	                ),
313	                "SuperAdmin " + adminUser.getEmail() + " started impersonation session for tenant: " + tenant.getName()
314	        );
315	
316	        log.info("Impersonation JWT minted and session started: admin={} targetTenant={}",
317	                adminUser.getId(), targetTenantId);
318	        return impersonationJwt;
319	    }
