321	    /**
322	     * Revoke an outstanding impersonation session (H-3).
323	     *
324	     * <p>Extracts the dedicated {@code impersonationJti} from the supplied impersonation
325	     * token and blacklists it via {@link TokenBlacklistService#revokeImpersonationToken}.
326	     * {@link com.nulogic.common.security.JwtTokenProvider#validateToken} consults this
327	     * blacklist for impersonation tokens, so the session is rejected immediately rather
328	     * than living out its natural 15-minute TTL. The SuperAdmin's own (home) session is
329	     * unaffected because revocation keys off the impersonationJti, not the userId.</p>
330	     */
331	    @Transactional
332	    public void revokeImpersonationToken(String impersonationToken) {
333	        if (!jwtTokenProvider.isImpersonationToken(impersonationToken)) {
334	            throw new IllegalArgumentException("Token is not an impersonation token");
335	        }
336	        UUID impersonationJti = jwtTokenProvider.getImpersonationJtiFromToken(impersonationToken);
337	        if (impersonationJti == null) {
338	            throw new IllegalArgumentException("Impersonation token has no revocation key");
339	        }
340	        Date expiration = jwtTokenProvider.getExpirationFromToken(impersonationToken);
341	        tokenBlacklistService.revokeImpersonationToken(impersonationJti, expiration);
342	        log.info("SuperAdmin revoked impersonation session {}", impersonationJti);
343	    }
