384	    /**
385	     * Suspend a tenant — immediately revokes access by invalidating all caches.
386	     *
387	     * <p>This method performs three cache-invalidation steps to ensure the suspended
388	     * tenant cannot continue making requests:
389	     * <ol>
390	     *   <li>Persist the status change to the database.</li>
391	     *   <li>Remove the tenant from {@link TenantFilter}'s in-memory valid-tenant cache
392	     *       so subsequent requests are rejected immediately (SEC-B10).</li>
393	     *   <li>Flush all Redis caches scoped to the tenant via {@link TenantCacheManager}
394	     *       to prevent stale data from being served.</li>
395	     * </ol>
396	     */
397	    @Transactional
398	    public Tenant suspendTenant(UUID tenantId) {
399	        log.info("SuperAdmin suspending tenant: {}", tenantId);
400	
401	        Tenant tenant = tenantRepository.findById(tenantId)
402	                .orElseThrow(() -> new ResourceNotFoundException("Tenant not found with ID: " + tenantId));
403	
404	        tenant.suspend(); // throws IllegalStateException if not ACTIVE
405	        tenantRepository.save(tenant);
406	
407	        // Immediately invalidate caches so the tenant is locked out (SEC-B10)
408	        tenantFilter.invalidateTenant(tenantId);
409	        tenantCacheManager.invalidateTenantCaches(tenantId);
410	        // Sprint-4 follow-up: bypass the 30-second TenantStatusCache TTL so the
411	        // JwtAuthenticationFilter sees the SUSPENDED status on the very next request.
412	        tenantStatusCache.evict(tenantId);
413	        // Sprint-4 M-C4: drop a tenant-wide revocation marker so any token already in flight
414	        // for users of this tenant is treated as revoked. The primary defense remains the
415	        // JWT-filter tenant-status check; this is belt-and-braces for race windows where a
416	        // token was minted just before suspension.
417	        tokenBlacklistService.revokeAllTokensForTenant(tenantId, Instant.now());
418	
419	        // Audit log the suspension
420	        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();
421	        auditLogService.logAction(
422	                "TENANT",
423	                tenantId,
424	                com.nulogic.domain.audit.AuditLog.AuditAction.UPDATE,
425	                Map.of("previousStatus", "ACTIVE", "newStatus", "SUSPENDED"),
426	                Map.of("admin_user_id", currentUserId),
427	                "SuperAdmin suspended tenant: " + tenant.getName()
428	        );
429	
430	        log.info("Tenant {} suspended successfully. Caches invalidated.", tenantId);
431	        return tenant;
432	    }
