466	    /**
467	     * Update the IANA timezone for a tenant and invalidate the per-tenant {@link ZoneId}
468	     * cache in {@link TenantTimeService} so the change takes effect within the JVM without
469	     * waiting for the 1-hour cache TTL.
470	     *
471	     * <p><strong>Why invalidate AFTER commit.</strong> If we invalidated before the
472	     * transaction commits, a parallel request could:
473	     * <ol>
474	     *   <li>see the invalidation,</li>
475	     *   <li>call {@code zoneFor(tenantId)} which DB-reads the <em>old</em> timezone (the
476	     *       update isn't visible to another connection until commit), and</li>
477	     *   <li>repopulate the cache with the stale value — leaving us right back where we
478	     *       started for up to another TTL window.</li>
479	     * </ol>
480	     * Deferring to {@code afterCommit} closes that race: by the time the cache is cleared,
481	     * any subsequent read will see the new row. If the transaction rolls back, the cache
482	     * is left untouched (correct — the DB value didn't change).</p>
483	     *
484	     * <p><strong>Multi-pod caveat.</strong> This invalidates only the local JVM cache.
485	     * Other pods will continue serving the old zone for up to 1 hour. That is acceptable
486	     * for admin-triggered changes (rare, plannable) per the wave-10 audit. If we need
487	     * cross-pod immediate consistency we should publish a Redis pub/sub event and have
488	     * each pod subscribe — out of scope here.</p>
489	     *
490	     * @param tenantId target tenant
491	     * @param newTimezone IANA zone-id; must match the V165 regex (already enforced at
492	     *                    the controller boundary, re-validated here as defence-in-depth)
493	     * @return the updated tenant
494	     */
495	    @Transactional
496	    public Tenant updateTenantTimezone(UUID tenantId, String newTimezone) {
497	        log.info("SuperAdmin updating timezone for tenant {} to '{}'", tenantId, newTimezone);
498	
499	        if (newTimezone == null || newTimezone.isBlank()) {
500	            throw new ValidationException("Timezone is required");
501	        }
502	
503	        // Semantic validation — the regex at the controller checks shape, but only ZoneId.of
504	        // can tell us whether the string is a known zone-id. Better to fail here with a clear
505	        // error than to write a row that TenantTimeService will silently fall back from.
506	        try {
507	            ZoneId.of(newTimezone);
508	        } catch (DateTimeException e) {
509	            throw new ValidationException("Unknown IANA timezone: '" + newTimezone + "'");
510	        }
511	
512	        Tenant tenant = tenantRepository.findById(tenantId)
513	                .orElseThrow(() -> new ResourceNotFoundException("Tenant not found with ID: " + tenantId));
514	
515	        String previousTimezone = tenant.getTimezone();
516	        if (newTimezone.equals(previousTimezone)) {
517	            log.info("Tenant {} timezone already '{}' — no-op", tenantId, newTimezone);
518	            return tenant;
519	        }
520	
521	        tenant.setTimezone(newTimezone);
522	        tenantRepository.save(tenant);
523	
524	        // Defer cache invalidation to afterCommit so a concurrent read cannot repopulate
525	        // the cache with the pre-commit (stale) value. Mirrors the DomainEventPublisher
526	        // pattern used elsewhere in the codebase.
527	        if (TransactionSynchronizationManager.isActualTransactionActive()) {
528	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
529	                @Override
530	                public void afterCommit() {
531	                    tenantTimeService.invalidate(tenantId);
532	                    log.info("TenantTimeService cache invalidated for tenant {} after timezone commit", tenantId);
533	                }
534	            });
535	        } else {
536	            // Defensive branch — @Transactional on this method guarantees a tx is active,
537	            // but if a caller ever bypasses the proxy (e.g. self-invocation, test setup),
538	            // invalidate inline so behaviour is still correct.
539	            tenantTimeService.invalidate(tenantId);
540	        }
541	
542	        // Audit log the timezone change
543	        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();
544	        auditLogService.logAction(
545	                "TENANT",
546	                tenantId,
547	                com.nulogic.domain.audit.AuditLog.AuditAction.UPDATE,
548	                Map.of("previousTimezone", previousTimezone == null ? "" : previousTimezone,
549	                        "newTimezone", newTimezone),
550	                Map.of("admin_user_id", currentUserId == null ? "" : currentUserId.toString()),
551	                "SuperAdmin updated timezone for tenant: " + tenant.getName()
552	        );
553	
554	        log.info("Tenant {} timezone updated from '{}' to '{}'", tenantId, previousTimezone, newTimezone);
555	        return tenant;
556	    }
