717	                .status(tenant.getStatus() != null ? tenant.getStatus().name() : "ACTIVE")
718	                .employeeCount(employeeCount)
719	                .userCount(userCount)
720	                .storageUsageBytes(storageUsageBytes)
721	                .createdAt(tenant.getCreatedAt())
722	                .lastActivityAt(lastActivityAt)
