{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01QR4WmYE14RfCXiadKTmJW1","type":"tool_result","content":"1\tpackage com.nulogic.infrastructure.audit.repository;\n2\t\n3\timport com.nulogic.domain.audit.AuditLog;\n4\timport com.nulogic.domain.audit.AuditLog.AuditAction;\n5\timport org.springframework.data.domain.Page;\n6\timport org.springframework.data.domain.Pageable;\n7\timport org.springframework.data.jpa.repository.JpaRepository;\n8\timport org.springframework.data.jpa.repository.JpaSpecificationExecutor;\n9\timport org.springframework.data.jpa.repository.Query;\n10\timport org.springframework.data.repository.query.Param;\n11\timport org.springframework.stereotype.Repository;\n12\t\n13\timport java.time.LocalDateTime;\n14\timport java.util.List;\n15\timport java.util.UUID;\n16\t\n17\t@Repository\n18\tpublic interface AuditLogRepository extends JpaRepository<AuditLog, UUID>, JpaSpecificationExecutor<AuditLog> {\n19\t\n20\t    // Tenant-aware queries\n21\t    Page<AuditLog> findAllByTenantIdOrderByCreatedAtDesc(UUID tenantId, Pageable pageable);\n22\t\n23\t    Page<AuditLog> findByTenantIdAndEntityTypeOrderByCreatedAtDesc(UUID tenantId, String entityType, Pageable pageable);\n24\t\n25\t    Page<AuditLog> findByTenantIdAndEntityTypeAndEntityIdOrderByCreatedAtDesc(\n26\t            UUID tenantId, String entityType, UUID entityId, Pageable pageable);\n27\t\n28\t    Page<AuditLog> findByTenantIdAndActorIdOrderByCreatedAtDesc(UUID tenantId, UUID actorId, Pageable pageable);\n29\t\n30\t    Page<AuditLog> findByTenantIdAndActionOrderByCreatedAtDesc(UUID tenantId, AuditAction action, Pageable pageable);\n31\t\n32\t    // Date range queries\n33\t    @Query(\"SELECT a FROM AuditLog a WHERE a.tenantId = :tenantId AND a.createdAt BETWEEN :startDate AND :endDate ORDER BY a.createdAt DESC\")\n34\t    Page<AuditLog> findByTenantIdAndDateRange(\n35\t            @Param(\"tenantId\") UUID tenantId,\n36\t            @Param(\"startDate\") LocalDateTime startDate,\n37\t            @Param(\"endDate\") LocalDateTime endDate,\n38\t            Pageable pageable);\n39\t\n40\t    // Combined filters\n41\t    @Query(\"SELECT a FROM AuditLog a WHERE a.tenantId = :tenantId \" +\n42\t            \"AND (:entityType IS NULL OR a.entityType = :entityType) \" +\n43\t            \"AND (:action IS NULL OR a.action = :action) \" +\n44\t            \"AND (:actorId IS NULL OR a.actorId = :actorId) \" +\n45\t            \"AND (CAST(:startDate AS LocalDateTime) IS NULL OR a.createdAt >= :startDate) \" +\n46\t            \"AND (CAST(:endDate AS LocalDateTime) IS NULL OR a.createdAt <= :endDate) \" +\n47\t            \"ORDER BY a.createdAt DESC\")\n48\t    Page<AuditLog> searchAuditLogs(\n49\t            @Param(\"tenantId\") UUID tenantId,\n50\t            @Param(\"entityType\") String entityType,\n51\t            @Param(\"action\") AuditAction action,\n52\t            @Param(\"actorId\") UUID actorId,\n53\t            @Param(\"startDate\") LocalDateTime startDate,\n54\t            @Param(\"endDate\") LocalDateTime endDate,\n55\t            Pageable pageable);\n56\t\n57\t    // Recent audit logs for an entity\n58\t    List<AuditLog> findTop10ByTenantIdAndEntityTypeAndEntityIdOrderByCreatedAtDesc(\n59\t            UUID tenantId, String entityType, UUID entityId);\n60\t\n61\t    // Recent activity feed for a tenant (used by dashboard).\n62\t    // Spring Data derived finder — avoids constructing a PageRequest for a fixed top-N.\n63\t    List<AuditLog> findTop10ByTenantIdOrderByCreatedAtDesc(UUID tenantId);\n64\t\n65\t    // Statistics\n66\t    @Query(\"SELECT COUNT(a) FROM AuditLog a WHERE a.tenantId = :tenantId AND a.createdAt BETWEEN :startDate AND :endDate\")\n67\t    long countByTenantIdAndDateRange(\n68\t            @Param(\"tenantId\") UUID tenantId,\n69\t            @Param(\"startDate\") LocalDateTime startDate,\n70\t            @Param(\"endDate\") LocalDateTime endDate);\n71\t\n72\t    @Query(\"SELECT a.action, COUNT(a) FROM AuditLog a WHERE a.tenantId = :tenantId \" +\n73\t            \"AND a.createdAt BETWEEN :startDate AND :endDate GROUP BY a.action\")\n74\t    List<Object[]> countByActionForDateRange(\n75\t            @Param(\"tenantId\") UUID tenantId,\n76\t            @Param(\"startDate\") LocalDateTime startDate,\n77\t            @Param(\"endDate\") LocalDateTime endDate);\n78\t\n79\t    @Query(\"SELECT a.entityType, COUNT(a) FROM AuditLog a WHERE a.tenantId = :tenantId \" +\n80\t            \"AND a.createdAt BETWEEN :startDate AND :endDate GROUP BY a.entityType ORDER BY COUNT(a) DESC\")\n81\t    List<Object[]> countByEntityTypeForDateRange(\n82\t            @Param(\"tenantId\") UUID tenantId,\n83\t            @Param(\"startDate\") LocalDateTime startDate,\n84\t            @Param(\"endDate\") LocalDateTime endDate);\n85\t\n86\t    @Query(\"SELECT a.actorId, a.actorEmail, COUNT(a) FROM AuditLog a WHERE a.tenantId = :tenantId \" +\n87\t            \"AND a.createdAt BETWEEN :startDate AND :endDate GROUP BY a.actorId, a.actorEmail ORDER BY COUNT(a) DESC\")\n88\t    List<Object[]> countByActorForDateRange(\n89\t            @Param(\"tenantId\") UUID tenantId,\n90\t            @Param(\"startDate\") LocalDateTime startDate,\n91\t            @Param(\"endDate\") LocalDateTime endDate);\n92\t\n93\t    @Query(\"SELECT DATE(a.createdAt), COUNT(a) FROM AuditLog a WHERE a.tenantId = :tenantId \" +\n94\t            \"AND a.createdAt BETWEEN :startDate AND :endDate GROUP BY DATE(a.createdAt) ORDER BY DATE(a.createdAt)\")\n95\t    List<Object[]> countByDayForDateRange(\n96\t            @Param(\"tenantId\") UUID tenantId,\n97\t            @Param(\"startDate\") LocalDateTime startDate,\n98\t            @Param(\"endDate\") LocalDateTime endDate);\n99\t\n100\t    // Security-related queries\n101\t    @Query(\"SELECT a FROM AuditLog a WHERE a.tenantId = :tenantId \" +\n102\t            \"AND a.action IN ('LOGIN', 'LOGOUT', 'PASSWORD_CHANGE', 'PERMISSION_CHANGE') \" +\n103\t            \"AND a.createdAt BETWEEN :startDate AND :endDate ORDER BY a.createdAt DESC\")\n104\t    Page<AuditLog> findSecurityEvents(\n105\t            @Param(\"tenantId\") UUID tenantId,\n106\t            @Param(\"startDate\") LocalDateTime startDate,\n107\t            @Param(\"endDate\") LocalDateTime endDate,\n108\t            Pageable pageable);\n109\t\n110\t    // Failed actions (for compliance)\n111\t    @Query(\"SELECT a FROM AuditLog a WHERE a.tenantId = :tenantId \" +\n112\t            \"AND a.changes LIKE '%failed%' OR a.changes LIKE '%error%' \" +\n113\t            \"ORDER BY a.createdAt DESC\")\n114\t    Page<AuditLog> findFailedActions(@Param(\"tenantId\") UUID tenantId, Pageable pageable);\n115\t\n116\t    // Count by tenant\n117\t    long countByTenantId(UUID tenantId);\n118\t\n119\t    long countByTenantIdAndEntityType(UUID tenantId, String entityType);\n120\t\n121\t    long countByTenantIdAndActorId(UUID tenantId, UUID actorId);\n122\t\n123\t    // ==================== Cross-tenant queries (SUPER_ADMIN — wave-3 M-C2) ====================\n124\t\n125\t    /**\n126\t     * List ALL audit logs across every tenant, ordered by createdAt desc.\n127\t     * Used only by {@code AuditLogService.getAllAuditLogsCrossTenant}, which is\n128\t     * gated by SYSTEM:ADMIN permission + a defense-in-depth re-check in the service.\n129\t     */\n130\t    Page<AuditLog> findAllByOrderByCreatedAtDesc(Pageable pageable);\n131\t\n132\t    /**\n133\t     * Cross-tenant search with an optional {@code tenantId} filter. When the\n134\t     * parameter is {@code null}, the predicate degenerates to \"any tenant\".\n135\t     * Mirrors {@link #searchAuditLogs} but with tenantId as a nullable filter\n136\t     * rather than a required scope.\n137\t     */\n138\t    @Query(\"SELECT a FROM AuditLog a WHERE \" +\n139\t            \"(:tenantId IS NULL OR a.tenantId = :tenantId) \" +\n140\t            \"AND (:entityType IS NULL OR a.entityType = :entityType) \" +\n141\t            \"AND (:action IS NULL OR a.action = :action) \" +\n142\t            \"AND (:actorId IS NULL OR a.actorId = :actorId) \" +\n143\t            \"AND (CAST(:startDate AS LocalDateTime) IS NULL OR a.createdAt >= :startDate) \" +\n144\t            \"AND (CAST(:endDate AS LocalDateTime) IS NULL OR a.createdAt <= :endDate) \" +\n145\t            \"ORDER BY a.createdAt DESC\")\n146\t    Page<AuditLog> searchCrossTenant(\n147\t            @Param(\"tenantId\") UUID tenantId,\n148\t            @Param(\"entityType\") String entityType,\n149\t            @Param(\"action\") AuditAction action,\n150\t            @Param(\"actorId\") UUID actorId,\n151\t            @Param(\"startDate\") LocalDateTime startDate,\n152\t            @Param(\"endDate\") LocalDateTime endDate,\n153\t            Pageable pageable);\n154\t\n155\t    // Legacy queries (kept for backward compatibility)\n156\t    Page<AuditLog> findByEntityTypeAndEntityIdOrderByCreatedAtDesc(String entityType, UUID entityId, Pageable pageable);\n157\t\n158\t    Page<AuditLog> findByActorIdOrderByCreatedAtDesc(UUID actorId, Pageable pageable);\n159\t\n160\t    Page<AuditLog> findByEntityTypeOrderByCreatedAtDesc(String entityType, Pageable pageable);\n161\t\n162\t    Page<AuditLog> findByActionOrderByCreatedAtDesc(AuditAction action, Pageable pageable);\n163\t\n164\t    @Query(\"SELECT a FROM AuditLog a WHERE a.createdAt BETWEEN :startDate AND :endDate ORDER BY a.createdAt DESC\")\n165\t    Page<AuditLog> findByDateRange(@Param(\"startDate\") LocalDateTime startDate, @Param(\"endDate\") LocalDateTime endDate, Pageable pageable);\n166\t\n167\t    Page<AuditLog> findByEntityTypeAndActionOrderByCreatedAtDesc(String entityType, AuditAction action, Pageable pageable);\n168\t\n169\t    List<AuditLog> findTop10ByEntityTypeAndEntityIdOrderByCreatedAtDesc(String entityType, UUID entityId);\n170\t\n171\t    long countByEntityType(String entityType);\n172\t\n173\t    long countByActorId(UUID actorId);\n174\t}\n175\t"}]},"parent_tool_use_id":"toolu_01JgAM9Ax18NS4WRFCdnZTFn","sess