{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01MQtsApahD3DDZaWBGDaXba","type":"tool_result","content":"1\tpackage com.nulogic.api.admin.controller;\n2\t\n3\timport com.nulogic.api.admin.dto.*;\n4\timport com.nulogic.application.admin.service.SystemAdminService;\n5\timport com.nulogic.common.config.CookieConfig;\n6\timport com.nulogic.common.security.RequiresPermission;\n7\timport com.nulogic.common.security.SecurityContext;\n8\timport io.swagger.v3.oas.annotations.Operation;\n9\timport io.swagger.v3.oas.annotations.Parameter;\n10\timport io.swagger.v3.oas.annotations.tags.Tag;\n11\timport jakarta.servlet.http.HttpServletResponse;\n12\timport jakarta.validation.Valid;\n13\timport lombok.RequiredArgsConstructor;\n14\timport lombok.extern.slf4j.Slf4j;\n15\timport org.springframework.data.domain.Page;\n16\timport org.springframework.data.domain.Pageable;\n17\timport org.springframework.data.web.PageableDefault;\n18\timport org.springframework.http.HttpHeaders;\n19\timport org.springframework.http.HttpStatus;\n20\timport org.springframework.http.ResponseEntity;\n21\timport org.springframework.web.bind.annotation.*;\n22\t\n23\timport java.util.UUID;\n24\t\n25\timport static com.nulogic.common.security.Permission.SYSTEM_ADMIN;\n26\t\n27\t/**\n28\t * SuperAdmin system-wide mission control endpoint\n29\t * All endpoints require SYSTEM_ADMIN permission (SuperAdmin role only)\n30\t * Provides cross-tenant visibility and control\n31\t */\n32\t@RestController\n33\t@RequestMapping(\"/api/v1/admin/system\")\n34\t@RequiredArgsConstructor\n35\t@Slf4j\n36\t@Tag(name = \"System Admin\", description = \"SuperAdmin mission control and cross-tenant management endpoints\")\n37\tpublic class SystemAdminController {\n38\t\n39\t    private final SystemAdminService systemAdminService;\n40\t    private final CookieConfig cookieConfig;\n41\t\n42\t    /**\n43\t     * Get comprehensive system overview\n44\t     * Returns aggregated metrics across all tenants\n45\t     */\n46\t    @GetMapping(\"/overview\")\n47\t    @Operation(summary = \"Get system overview\", description = \"Returns comprehensive cross-tenant system metrics including total tenants, active users, pending approvals, and storage usage\")\n48\t    @RequiresPermission(SYSTEM_ADMIN)\n49\t    public ResponseEntity<SystemOverviewDTO> getSystemOverview() {\n50\t        log.info(\"SuperAdmin requesting system overview\");\n51\t        SystemOverviewDTO overview = systemAdminService.getSystemOverview();\n52\t        return ResponseEntity.ok(overview);\n53\t    }\n54\t\n55\t    /**\n56\t     * Get paginated list of all tenants\n57\t     * SuperAdmin only - includes metrics for each tenant\n58\t     */\n59\t    @GetMapping(\"/tenants\")\n60\t    @Operation(summary = \"Get paginated tenant list\", description = \"Returns a paginated list of all tenants with basic metrics including employee count, user count, and storage usage\")\n61\t    @RequiresPermission(SYSTEM_ADMIN)\n62\t    public ResponseEntity<Page<TenantListItemDTO>> getTenantList(\n63\t            @PageableDefault(size = 20, page = 0) Pageable pageable) {\n64\t        log.info(\"SuperAdmin requesting tenant list, page: {}, size: {}\",\n65\t                pageable.getPageNumber(), pageable.getPageSize());\n66\t        Page<TenantListItemDTO> tenants = systemAdminService.getTenantList(pageable);\n67\t        return ResponseEntity.ok(tenants);\n68\t    }\n69\t\n70\t    /**\n71\t     * Get deep-dive metrics for a specific tenant\n72\t     * SuperAdmin only - returns comprehensive metrics for a single tenant\n73\t     */\n74\t    @GetMapping(\"/tenants/{tenantId}/metrics\")\n75\t    @Operation(summary = \"Get tenant metrics\", description = \"Returns detailed metrics for a specific tenant including active users, employee count, pending approvals, and last activity timestamp\")\n76\t    @RequiresPermission(SYSTEM_ADMIN)\n77\t    public ResponseEntity<TenantMetricsDTO> getTenantMetrics(\n78\t            @Parameter(description = \"Tenant ID\")\n79\t            @PathVariable UUID tenantId) {\n80\t        log.info(\"SuperAdmin requesting metrics for tenant: {}\", tenantId);\n81\t        TenantMetricsDTO metrics = systemAdminService.getTenantMetrics(tenantId);\n82\t        return ResponseEntity.ok(metrics);\n83\t    }\n84\t\n85\t    /**\n86\t     * Get platform growth metrics over the last N months\n87\t     * Returns cumulative tenant, employee, and user counts by month\n88\t     */\n89\t    @GetMapping(\"/growth-metrics\")\n90\t    @Operation(summary = \"Get platform growth metrics\", description = \"Returns monthly cumulative counts of tenants, employees, and active users over the specified number of months\")\n91\t    @RequiresPermission(SYSTEM_ADMIN)\n92\t    public ResponseEntity<GrowthMetricsDTO> getGrowthMetrics(\n93\t            @Parameter(description = \"Number of months of history (default 6, max 24)\")\n94\t            @RequestParam(defaultValue = \"6\") int months) {\n95\t        log.info(\"SuperAdmin requesting growth metrics for last {} months\", months);\n96\t        GrowthMetricsDTO metrics = systemAdminService.getGrowthMetrics(Math.min(months, 24));\n97\t        return ResponseEntity.ok(metrics);\n98\t    }\n99\t\n100\t    /**\n101\t     * Suspend a tenant — blocks all access immediately.\n102\t     * Invalidates TenantFilter cache + Redis caches (SEC-B10).\n103\t     */\n104\t    @PostMapping(\"/tenants/{tenantId}/suspend\")\n105\t    @Operation(summary = \"Suspend tenant\", description = \"Suspend a tenant, immediately revoking access by invalidating all caches\")\n106\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n107\t    public ResponseEntity<TenantStatusDTO> suspendTenant(\n108\t            @Parameter(description = \"Tenant ID to suspend\")\n109\t            @PathVariable UUID tenantId) {\n110\t        log.info(\"SuperAdmin suspending tenant: {}\", tenantId);\n111\t        var tenant = systemAdminService.suspendTenant(tenantId);\n112\t        return ResponseEntity.ok(TenantStatusDTO.builder()\n113\t                .tenantId(tenant.getId())\n114\t                .name(tenant.getName())\n115\t                .status(tenant.getStatus().name())\n116\t                .build());\n117\t    }\n118\t\n119\t    /**\n120\t     * Re-activate a previously suspended or pending tenant.\n121\t     */\n122\t    @PostMapping(\"/tenants/{tenantId}/activate\")\n123\t    @Operation(summary = \"Activate tenant\", description = \"Re-activate a suspended or pending tenant\")\n124\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n125\t    public ResponseEntity<TenantStatusDTO> activateTenant(\n126\t            @Parameter(description = \"Tenant ID to activate\")\n127\t            @PathVariable UUID tenantId) {\n128\t        log.info(\"SuperAdmin activating tenant: {}\", tenantId);\n129\t        var tenant = systemAdminService.activateTenant(tenantId);\n130\t        return ResponseEntity.ok(TenantStatusDTO.builder()\n131\t                .tenantId(tenant.getId())\n132\t                .name(tenant.getName())\n133\t                .status(tenant.getStatus().name())\n134\t                .build());\n135\t    }\n136\t\n137\t    /**\n138\t     * Update a tenant's IANA timezone.\n139\t     *\n140\t     * <p>Persists the new zone-id on the tenant row and (after the transaction commits)\n141\t     * invalidates the per-tenant {@link com.nulogic.common.util.TenantTimeService} cache\n142\t     * entry so all scheduled jobs and request handlers running in this JVM pick up the\n143\t     * new zone on the next call. Other pods catch up within the cache TTL (1 hour).</p>\n144\t     */\n145\t    @PatchMapping(\"/tenants/{tenantId}/timezone\")\n146\t    @Operation(summary = \"Update tenant timezone\",\n147\t            description = \"Update the IANA timezone for a tenant and invalidate the TenantTimeService cache entry on commit\")\n148\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n149\t    public ResponseEntity<TenantStatusDTO> updateTenantTimezone(\n150\t            @Parameter(description = \"Tenant ID\")\n151\t            @PathVariable UUID tenantId,\n152\t            @Valid @RequestBody UpdateTenantTimezoneRequest request) {\n153\t        log.info(\"SuperAdmin updating timezone for tenant {} to '{}'\", tenantId, request.getTimezone());\n154\t        var tenant = systemAdminService.updateTenantTimezone(tenantId, request.getTimezone());\n155\t        return ResponseEntity.ok(TenantStatusDTO.builder()\n156\t                .tenantId(tenant.getId())\n157\t                .name(tenant.getName())\n158\t                .status(tenant.getStatus().name())\n159\t                .build());\n160\t    }\n161\t\n162\t    /**\n163\t     * Phase 1 of the two-phase impersonation flow (M-12).\n164\t     *\n165\t     * <p>Generates a short-lived (60s), single-use opaque exchange token stored in Redis.\n166\t     * The impersonation JWT is NOT minted here — it is minted only when the client presents\n167\t     * the exchange token to {@link #consumeImpersonationExchangeToken}, where it is placed\n168\t     * directly into an httpOnly cookie. This design ensures the impersonation JWT is never\n169\t     * exposed to JavaScript.</p>\n170\t     *\n171\t     * <p>Returns: {@code 200 OK} with exchange token + tenant info for UI confirmation.</p>\n172\t     */\n173\t    @PostMapping(\"/tenants/{tenantId}/impersonate\")\n174\t    @Operation(summary = \"Generate impersonation exchange token (phase 1 of 2)\",\n175\t            description = \"Generates a short-lived (60s) single-use opaque exchange token. \" +\n176\t                    \"Present the exchangeToken to POST /impersonate/consume to obtain the \" +\n177\t                    \"impersonated session cookie. The JWT is never returned here.\")\n178\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n179\t    public ResponseEntity<ImpersonationExchangeResponse> generateImpersonationExchangeToken(\n180\t            @Parameter(description = \"Target tenant ID for impersonation\")\n181\t            @PathVariable UUID tenantId) {\n182\t        log.info(\"SuperAdmin initiating impersonation exchange token for tenant: {}\", tenantId);\n183\t        ImpersonationExchangeResponse response =\n184\t                systemAdminService.generateImpersonationExchangeToken(tenantId);\n185\t        return ResponseEntity.ok(response);\n186\t    }\n187\t\n188\t    /**\n189\t     * Phase 2 of the two-phase impersonation flow (M-12).\n190\t     *\n191\t     * <p>Atomically consumes the exchange token (Redis single-use enforcement), mints the\n192\t     * impersonation JWT, and places it in an httpOnly access-token cookie identical to the\n193\t     * normal login cookie. The impersonation JWT is never returned in the response body —\n194\t     * it exists only in the cookie jar, inaccessible to JavaScript.</p>\n195\t     *\n196\t     * <p>Security controls applied here:\n197\t     * <ul>\n198\t     *   <li>{@code @RequiresPermission(revalidate=true)}: verifies SYSTEM_ADMIN from DB,\n199\t     *       not from cached JWT claims, immediately before consumption.</li>\n200\t     *   <li>Issuer binding: service verifies the consuming admin matches the token issuer.</li>\n201\t     *   <li>Single-use: Redis GETDEL atomicity prevents replay.</li>\n202\t     *   <li>Audit log: full impersonation event written asynchronously.</li>\n203\t     * </ul></p>\n204\t     *\n205\t     * <p>Returns: {@code 204 No Content} on success (no body — the session is in the cookie).\n206\t     * Returns {@code 403} if the exchange token is invalid, expired, or already used.</p>\n207\t     */\n208\t    @PostMapping(\"/impersonate/consume\")\n209\t    @Operation(summary = \"Consume impersonation exchange token (phase 2 of 2)\",\n210\t            description = \"Validates and consumes the exchange token from phase 1 (single-use, 60s TTL). \" +\n211\t                    \"On success, sets the impersonation JWT as an httpOnly access-token cookie and returns 204. \" +\n212\t                    \"The JWT is never present in the response body.\")\n213\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n214\t    public ResponseEntity<Void> consumeImpersonationExchangeToken(\n215\t            @Valid @RequestBody ConsumeImpersonationRequest request,\n216\t            HttpServletResponse response) {\n217\t        log.info(\"SuperAdmin consuming impersonation exchange token\");\n218\t        String impersonationJwt = systemAdminService.consumeImpersonationExchangeToken(\n219\t                request.getExchangeToken());\n220\t\n221\t        // Place the impersonation JWT in the same httpOnly cookie the normal login flow uses.\n222\t        // The cookie is not readable by JavaScript (HttpOnly). The JwtAuthenticationFilter\n223\t        // already understands impersonation tokens: it sets SecurityContext + TenantContext\n224\t        // from the token's tenantId / impersonatorId claims.\n225\t        response.addHeader(HttpHeaders.SET_COOKIE,\n226\t                cookieConfig.createAccessTokenCookie(impersonationJwt).toString());\n227\t        // Also emit the hardened __Host- variant for clients that accept it (S10-J rollover).\n228\t        response.addHeader(HttpHeaders.SET_COOKIE,\n229\t                cookieConfig.createHardenedAccessTokenCookie(impersonationJwt).toString());\n230\t\n231\t        log.info(\"Impersonation session established via httpOnly cookie for admin={}\",\n232\t                SecurityContext.getCurrentUserId());\n233\t        return ResponseEntity.noContent().build();\n234\t    }\n235\t\n236\t    /**\n237\t     * Revoke an outstanding impersonation session (H-3).\n238\t     *\n239\t     * <p>Blacklists the supplied impersonation token's dedicated {@code impersonationJti}\n240\t     * so {@code validateToken} rejects it on the next request, without affecting the\n241\t     * SuperAdmin's own home session.</p>\n242\t     */\n243\t    @PostMapping(\"/impersonate/revoke\")\n244\t    @Operation(summary = \"Revoke impersonation token\", description = \"Immediately revoke a previously-issued impersonation session by blacklisting its impersonationJti\")\n245\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n246\t    public ResponseEntity<Void> revokeImpersonationToken(\n247\t            @Valid @RequestBody RevokeImpersonationRequest request) {\n248\t        log.info(\"SuperAdmin revoking impersonation token\");\n249\t        systemAdminService.revokeImpersonationToken(request.getToken());\n250\t        return ResponseEntity.noContent().build();\n251\t    }\n252\t\n253\t    /**\n254\t     * SuperAdmin-initiated password reset for a target user.\n255\t     *\n256\t     * <p>Generates a cryptographically-random 12-char temp password (URL-safe Base64),\n257\t     * persists the encoded hash, revokes all outstanding JWTs for the user, writes an\n258\t     * audit-log entry, and dispatches the temp password to the user via email. The temp\n259\t     * password is intentionally <em>not</em> included in the response — it is delivered\n260\t     * out-of-band to the user only.</p>\n261\t     *\n262\t     * <p>Closes wave-3 multi-tenant audit finding: \"no admin password reset path\".</p>\n263\t     */\n264\t    @PostMapping(\"/users/reset-password\")\n265\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n266\t    @Operation(summary = \"Admin-initiated user password reset\",\n267\t            description = \"Generates a random temp password, sets force-change flag on next login, emails user\")\n268\t    public AdminPasswordResetResponse adminResetPassword(@Valid @RequestBody AdminPasswordResetRequest request) {\n269\t        log.info(\"SuperAdmin initiating password reset for user {} (reason length={})\",\n270\t                request.getUserId(), request.getReason() == null ? 0 : request.getReason().length());\n271\t        return systemAdminService.adminResetPassword(request, SecurityContext.getCurrentUserId());\n272\t    }\n273\t}\n274\t"}]},"parent_tool_use_id":"toolu_01JgAM9Ax18NS4WRFCdnZTFn","session_id":"61db98fd-c720-4414-89bd-2708d1298a20","uuid":"f9440620-a620-4360-a0ee-003d05fc2f88","timestamp":"2026-06-11T19:26:22.414Z","subagent_type":"Explore","task_description":"Explore audit search endpoint+tests"}
