{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01JCq8Qme5913RxbDmjz8K3Q","type":"tool_result","content":"1\tpackage com.nulogic.application.admin.service;\n2\t\n3\timport com.nulogic.api.admin.dto.*;\n4\timport com.nulogic.application.document.service.StorageMetricsService;\n5\timport com.nulogic.application.notification.service.EmailNotificationService;\n6\timport com.nulogic.common.config.TenantCacheManager;\n7\timport com.nulogic.common.exception.BusinessException;\n8\timport com.nulogic.common.exception.ResourceNotFoundException;\n9\timport com.nulogic.common.exception.ValidationException;\n10\timport com.nulogic.common.security.JwtTokenProvider;\n11\timport com.nulogic.common.security.TenantContext;\n12\timport com.nulogic.common.security.TenantFilter;\n13\timport com.nulogic.common.security.TokenBlacklistService;\n14\timport com.nulogic.common.util.TenantTimeService;\n15\timport com.nulogic.domain.audit.AuditLog;\n16\timport com.nulogic.domain.tenant.Tenant;\n17\timport com.nulogic.domain.user.User;\n18\timport com.nulogic.domain.workflow.WorkflowExecution;\n19\timport com.nulogic.infrastructure.employee.repository.EmployeeRepository;\n20\timport com.nulogic.infrastructure.tenant.repository.TenantRepository;\n21\timport com.nulogic.infrastructure.tenant.repository.TenantStatusCache;\n22\timport com.nulogic.infrastructure.user.repository.UserRepository;\n23\timport com.nulogic.infrastructure.workflow.repository.WorkflowExecutionRepository;\n24\timport lombok.RequiredArgsConstructor;\n25\timport lombok.extern.slf4j.Slf4j;\n26\timport org.springframework.data.domain.Page;\n27\timport org.springframework.data.domain.Pageable;\n28\timport org.springframework.security.crypto.password.PasswordEncoder;\n29\timport org.springframework.stereotype.Service;\n30\timport org.springframework.transaction.annotation.Transactional;\n31\timport org.springframework.transaction.support.TransactionSynchronization;\n32\timport org.springframework.transaction.support.TransactionSynchronizationManager;\n33\t\n34\timport java.security.SecureRandom;\n35\timport java.time.DateTimeException;\n36\timport java.time.Instant;\n37\timport java.time.LocalDate;\n38\timport java.time.LocalDateTime;\n39\timport java.time.Month;\n40\timport java.time.ZoneId;\n41\timport java.time.format.TextStyle;\n42\timport java.util.*;\n43\timport java.util.stream.Collectors;\n44\t\n45\t/**\n46\t * Service for cross-tenant system administration (SuperAdmin only)\n47\t * All queries bypass tenant isolation and operate on the entire system\n48\t */\n49\t@Slf4j\n50\t@Service\n51\t@RequiredArgsConstructor\n52\tpublic class SystemAdminService {\n53\t\n54\t    /**\n55\t     * Cryptographically-secure RNG for temp-password byte generation.\n56\t     */\n57\t    private static final SecureRandom SECURE_RANDOM = new SecureRandom();\n58\t    private final TenantRepository tenantRepository;\n59\t    private final UserRepository userRepository;\n60\t    private final EmployeeRepository employeeRepository;\n61\t    private final WorkflowExecutionRepository workflowExecutionRepository;\n62\t    private final JwtTokenProvider jwtTokenProvider;\n63\t    private final com.nulogic.application.audit.service.AuditLogService auditLogService;\n64\t    private final TenantFilter tenantFilter;\n65\t    private final TenantCacheManager tenantCacheManager;\n66\t    private final StorageMetricsService storageMetricsService;\n67\t    private final AiUsageService aiUsageService;\n68\t    // Sprint-4 wave-3 follow-up: evict the per-request tenant-status cache so suspend/activate\n69\t    // propagate immediately rather than waiting for the 30-second TTL.\n70\t    private final TenantStatusCache tenantStatusCache;\n71\t    // Sprint-4: tenant-wide token revocation marker on suspension (belt-and-braces with the\n72\t    // JWT-filter tenant-status check from sprint 2, which remains the primary defense).\n73\t    private final TokenBlacklistService tokenBlacklistService;\n74\t    // Sprint-6 wave-3 (S6-B): SuperAdmin password-reset path — encode the new temp credential\n75\t    // and deliver it out-of-band via email so it never appears in the API response.\n76\t    private final PasswordEncoder passwordEncoder;\n77\t    private final EmailNotificationService emailNotificationService;\n78\t    // Wave-10 follow-up: tenant-timezone update flow must invalidate the per-tenant ZoneId\n79\t    // cache so a new zone takes effect within the JVM without waiting for the 1-hour TTL.\n80\t    private final TenantTimeService tenantTimeService;\n81\t    // M-12: two-phase impersonation — exchange-token store (Redis-backed, 60s TTL, single-use).\n82\t    private final ImpersonationExchangeTokenService impersonationExchangeTokenService;\n83\t\n84\t    /**\n85\t     * Get comprehensive system overview across all tenants\n86\t     */\n87\t    @Transactional(readOnly = true)\n88\t    public SystemOverviewDTO getSystemOverview() {\n89\t        log.info(\"SuperAdmin requesting system overview\");\n90\t\n91\t        long totalTenants = tenantRepository.count();\n92\t        long activeTenants = countActiveTenants();\n93\t        long totalEmployees = employeeRepository.count();\n94\t        long totalActiveUsers = countActiveUsers();\n95\t        long pendingApprovals = countPendingApprovals();\n96\t\n97\t        // Calculate storage usage from generated documents and document versions\n98\t        long storageUsageBytes = storageMetricsService.getStorageBytesAcrossAllTenants();\n99\t\n100\t        // Get total AI credits used across all tenants\n101\t        long aiCreditsUsed = aiUsageService.getAiCreditsUsedAcrossAllTenants();\n102\t\n103\t        return SystemOverviewDTO.builder()\n104\t                .totalTenants(totalTenants)\n105\t                .activeTenants(activeTenants)\n106\t                .totalEmployees(totalEmployees)\n107\t                .totalActiveUsers(totalActiveUsers)\n108\t                .storageUsageBytes(storageUsageBytes)\n109\t                .aiCreditsUsed(aiCreditsUsed)\n110\t                .pendingApprovals(pendingApprovals)\n111\t                .build();\n112\t    }\n113\t\n114\t    /**\n115\t     * Get paginated list of all tenants with basic metrics.\n116\t     *\n117\t     * <p>Uses batched aggregate queries to avoid N+1: employee count, user count, and last\n118\t     * activity are all fetched for the entire page in 3 queries rather than 3×N queries.</p>\n119\t     */\n120\t    @Transactional(readOnly = true)\n121\t    public Page<TenantListItemDTO> getTenantList(Pageable pageable) {\n122\t        log.info(\"SuperAdmin requesting tenant list, page: {}, size: {}\",\n123\t                pageable.getPageNumber(), pageable.getPageSize());\n124\t\n125\t        Page<Tenant> tenantsPage = tenantRepository.findAll(pageable);\n126\t\n127\t        // Collect IDs of tenants on this page for batch queries\n128\t        List<UUID> tenantIds = tenantsPage.getContent().stream()\n129\t                .map(Tenant::getId)\n130\t                .collect(Collectors.toList());\n131\t\n132\t        if (tenantIds.isEmpty()) {\n133\t            return tenantsPage.map(t -> mapToTenantListItem(t, 0L, 0L, null));\n134\t        }\n135\t\n136\t        // Batch queries — 2 queries for the whole page instead of 2×N\n137\t        Map<UUID, Long> employeeCountByTenant = employeeRepository.countByTenantIdIn(tenantIds)\n138\t                .stream().collect(Collectors.toMap(\n139\t                        r -> (UUID) r[0],\n140\t                        r -> (Long) r[1]\n141\t                ));\n142\t\n143\t        Map<UUID, Long> userCountByTenant = userRepository.countByTenantIdIn(tenantIds)\n144\t                .stream().collect(Collectors.toMap(\n145\t                        r -> (UUID) r[0],\n146\t                        r -> (Long) r[1]\n147\t                ));\n148\t\n149\t        // Last-activity lookup: still per-tenant but only for the page slice.\n150\t        // A tenant with no login history yields a null timestamp; Collectors.toMap\n151\t        // rejects null values (NPE), so build a null-tolerant map instead.\n152\t        Map<UUID, LocalDateTime> lastActivityByTenant = new HashMap<>();\n153\t        for (UUID id : tenantIds) {\n154\t            lastActivityByTenant.put(id, getLastActivityForTenant(id));\n155\t        }\n156\t\n157\t        return tenantsPage.map(tenant -> mapToTenantListItem(\n158\t                tenant,\n159\t                employeeCountByTenant.getOrDefault(tenant.getId(), 0L),\n160\t                userCountByTenant.getOrDefault(tenant.getId(), 0L),\n161\t                lastActivityByTenant.get(tenant.getId())\n162\t        ));\n163\t    }\n164\t\n165\t    /**\n166\t     * Get deep-dive metrics for a specific tenant\n167\t     */\n168\t    @Transactional(readOnly = true)\n169\t    public TenantMetricsDTO getTenantMetrics(UUID tenantId) {\n170\t        log.info(\"SuperAdmin requesting metrics for tenant: {}\", tenantId);\n171\t\n172\t        Tenant tenant = tenantRepository.findById(tenantId)\n173\t                .orElseThrow(() -> new ResourceNotFoundException(\"Tenant not found with ID: \" + tenantId));\n174\t\n175\t        long activeUsers = countActiveUsersForTenant(tenantId);\n176\t        long totalUsers = countUsersForTenant(tenantId);\n177\t        long employeeCount = countEmployeesForTenant(tenantId);\n178\t        long storageUsageBytes = storageMetricsService.getStorageBytesForTenant(tenantId);\n179\t        long pendingApprovals = countPendingApprovalsForTenant(tenantId);\n180\t        LocalDateTime lastActivityAt = getLastActivityForTenant(tenantId);\n181\t\n182\t        return TenantMetricsDTO.builder()\n183\t                .tenantId(tenantId)\n184\t                .tenantName(tenant.getName())\n185\t                .activeUsers(activeUsers)\n186\t                .totalUsers(totalUsers)\n187\t                .employeeCount(employeeCount)\n188\t                .storageUsageBytes(storageUsageBytes)\n189\t                .pendingApprovals(pendingApprovals)\n190\t                .lastActivityAt(lastActivityAt)\n191\t                .createdAt(tenant.getCreatedAt())\n192\t                .build();\n193\t    }\n194\t\n195\t    /**\n196\t     * Phase 1 of the two-phase impersonation flow (M-12).\n197\t     *\n198\t     * <p>Generates a short-lived (60s), single-use opaque exchange token stored in Redis.\n199\t     * The impersonation JWT is NOT minted here and is NOT returned to the caller — it is\n200\t     * minted only in {@link #consumeImpersonationExchangeToken} and placed directly in\n201\t     * an httpOnly cookie. This eliminates the prior gap where a 15-min JWT was returned\n202\t     * to the browser's JS context but never consumed.</p>\n203\t     *\n204\t     * @param tenantId the target tenant to impersonate\n205\t     * @return exchange token metadata (opaque token + TTL + tenant info for UI display)\n206\t     * @throws ResourceNotFoundException if the tenant does not exist\n207\t     * @throws IllegalStateException     if the Redis token store is unavailable (fail-closed)\n208\t     */\n209\t    @Transactional\n210\t    public ImpersonationExchangeResponse generateImpersonationExchangeToken(UUID tenantId) {\n211\t        log.info(\"SuperAdmin initiating impersonation exchange token generation for tenant: {}\", tenantId);\n212\t\n213\t        Tenant tenant = tenantRepository.findById(tenantId)\n214\t                .orElseThrow(() -> new ResourceNotFoundException(\"Tenant not found with ID: \" + tenantId));\n215\t\n216\t        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();\n217\t        // Verify the calling user exists in our DB (defence-in-depth against stale JWT).\n218\t        userRepository.findById(currentUserId)\n219\t                .orElseThrow(() -> new ResourceNotFoundException(\"Issuing admin not found\"));\n220\t\n221\t        String exchangeToken = impersonationExchangeTokenService.generateExchangeToken(currentUserId, tenantId);\n222\t\n223\t        // Audit-log exchange token generation. Full impersonation audit emitted at consume time.\n224\t        auditLogService.logAction(\n225\t                \"TENANT\",\n226\t                tenantId,\n227\t                AuditLog.AuditAction.LOGIN,\n228\t                Map.of(\"action\", \"impersonation_exchange_token_generated\"),\n229\t                Map.of(\"admin_user_id\", currentUserId.toString()),\n230\t                \"SuperAdmin generated impersonation exchange token for tenant: \" + tenant.getName()\n231\t        );\n232\t\n233\t        return ImpersonationExchangeResponse.builder()\n234\t                .exchangeToken(exchangeToken)\n235\t                .tenantId(tenantId.toString())\n236\t                .tenantName(tenant.getName())\n237\t                .expiresInSeconds(ImpersonationExchangeTokenService.TTL_SECONDS)\n238\t                .build();\n239\t    }\n240\t\n241\t    /**\n242\t     * Phase 2 of the two-phase impersonation flow (M-12).\n243\t     *\n244\t     * <p>Atomically consumes the exchange token from Redis (single-use enforcement),\n245\t     * mints an impersonation JWT, and returns it so the caller (SystemAdminController)\n246\t     * can place it in an httpOnly cookie. The JWT never enters a JS-readable context.</p>\n247\t     *\n248\t     * <p>Security properties enforced here:\n249\t     * <ul>\n250\t     *   <li><strong>Single-use:</strong> Redis GETDEL is atomic — a second call with the same token\n251\t     *       returns null immediately.</li>\n252\t     *   <li><strong>Expiry:</strong> Redis TTL (60s) enforced by the store; expired tokens also return\n253\t     *       null.</li>\n254\t     *   <li><strong>SuperAdmin-only issuance:</strong> the controller guard ({@code @RequiresPermission}\n255\t     *       with {@code revalidate=true}) verifies SYSTEM_ADMIN permission from the database.</li>\n256\t     *   <li><strong>Issuer binding:</strong> the exchange token embeds the admin's user ID; this\n257\t     *       method verifies the current caller matches the issuer.</li>\n258\t     *   <li><strong>Audit completeness:</strong> full impersonation event is written to the audit log.</li>\n259\t     * </ul></p>\n260\t     *\n261\t     * @param exchangeToken the opaque token from phase 1\n262\t     * @return a signed impersonation JWT to be set as an httpOnly cookie by the controller\n263\t     * @throws BusinessException if the exchange token is invalid, expired, or already used\n264\t     */\n265\t    @Transactional\n266\t    public String consumeImpersonationExchangeToken(String exchangeToken) {\n267\t        Map<String, UUID> payload = impersonationExchangeTokenService.consumeExchangeToken(exchangeToken);\n268\t        if (payload == null) {\n269\t            log.warn(\"Impersonation consume failed — exchange token not found, expired, or replayed\");\n270\t            throw new BusinessException(\"Impersonation exchange token is invalid, expired, or already used\");\n271\t        }\n272\t\n273\t        UUID adminUserId = payload.get(\"adminId\");\n274\t        UUID targetTenantId = payload.get(\"targetTenantId\");\n275\t\n276\t        Tenant tenant = tenantRepository.findById(targetTenantId)\n277\t                .orElseThrow(() -> new ResourceNotFoundException(\"Target tenant not found: \" + targetTenantId));\n278\t\n279\t        User adminUser = userRepository.findById(adminUserId)\n280\t                .orElseThrow(() -> new ResourceNotFoundException(\"Issuing admin user not found: \" + adminUserId));\n281\t\n282\t        // Issuer binding: verify the current caller is the same admin who generated the token.\n283\t        // The @RequiresPermission guard already verified SYSTEM_ADMIN; this closes the race\n284\t        // where Admin-A generates and Admin-B presents the same token.\n285\t        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();\n286\t        if (!adminUserId.equals(currentUserId)) {\n287\t            log.error(\"SEC: Impersonation exchange token issuer {} does not match caller {}\",\n288\t                    adminUserId, currentUserId);\n289\t            throw new BusinessException(\"Exchange token was not issued by the current user\");\n290\t        }\n291\t\n292\t        String impersonationJwt = jwtTokenProvider.generateImpersonationToken(\n293\t                adminUser.getId(),\n294\t                adminUser.getEmail(),\n295\t                targetTenantId,\n296\t                adminUser.getRoles().stream()\n297\t                        .map(r -> r.getCode())\n298\t                        .collect(Collectors.toSet())\n299\t        );\n300\t\n301\t        // Full impersonation audit: who impersonated whom, when, from which IP.\n302\t        auditLogService.logAction(\n303\t                \"TENANT\",\n304\t                targetTenantId,\n305\t                AuditLog.AuditAction.LOGIN,\n306\t                Map.of(\"action\", \"impersonation_session_started\"),\n307\t                Map.of(\n308\t                        \"admin_user_id\", adminUser.getId().toString(),\n309\t                        \"admin_email\", adminUser.getEmail(),\n310\t                        \"target_tenant_id\", targetTenantId.toString(),\n311\t                        \"target_tenant_name\", tenant.getName()\n312\t                ),\n313\t                \"SuperAdmin \" + adminUser.getEmail() + \" started impersonation session for tenant: \" + tenant.getName()\n314\t        );\n315\t\n316\t        log.info(\"Impersonation JWT minted and session started: admin={} targetTenant={}\",\n317\t                adminUser.getId(), targetTenantId);\n318\t        return impersonationJwt;\n319\t    }\n320\t\n321\t    /**\n322\t     * Revoke an outstanding impersonation session (H-3).\n323\t     *\n324\t     * <p>Extracts the dedicated {@code impersonationJti} from the supplied impersonation\n325\t     * token and blacklists it via {@link TokenBlacklistService#revokeImpersonationToken}.\n326\t     * {@link com.nulogic.common.security.JwtTokenProvider#validateToken} consults this\n327\t     * blacklist for impersonation tokens, so the session is rejected immediately rather\n328\t     * than living out its natural 15-minute TTL. The SuperAdmin's own (home) session is\n329\t     * unaffected because revocation keys off the impersonationJti, not the userId.</p>\n330\t     */\n331\t    @Transactional\n332\t    public void revokeImpersonationToken(String impersonationToken) {\n333\t        if (!jwtTokenProvider.isImpersonationToken(impersonationToken)) {\n334\t            throw new IllegalArgumentException(\"Token is not an impersonation token\");\n335\t        }\n336\t        UUID impersonationJti = jwtTokenProvider.getImpersonationJtiFromToken(impersonationToken);\n337\t        if (impersonationJti == null) {\n338\t            throw new IllegalArgumentException(\"Impersonation token has no revocation key\");\n339\t        }\n340\t        Date expiration = jwtTokenProvider.getExpirationFromToken(impersonationToken);\n341\t        tokenBlacklistService.revokeImpersonationToken(impersonationJti, expiration);\n342\t        log.info(\"SuperAdmin revoked impersonation session {}\", impersonationJti);\n343\t    }\n344\t\n345\t    /**\n346\t     * Get growth metrics over the last N months.\n347\t     *\n348\t     * <p>Previously loaded all tenants, employees, and users into heap and filtered in Java —\n349\t     * O(N) memory per entity type. Now issues 3 DB aggregate queries per month slice, which is\n350\t     * O(1) memory regardless of dataset size (PERF fix).</p>\n351\t     */\n352\t    @Transactional(readOnly = true)\n353\t    public GrowthMetricsDTO getGrowthMetrics(int months) {\n354\t        log.info(\"SuperAdmin requesting growth metrics for last {} months\", months);\n355\t\n356\t        // JVM-local: SuperAdmin cross-tenant aggregation — no single tenant zone applies.\n357\t        LocalDate now = LocalDate.now();\n358\t        List<GrowthMetricsDTO.MonthlyGrowth> growthList = new ArrayList<>();\n359\t\n360\t        for (int i = months - 1; i >= 0; i--) {\n361\t            LocalDate monthEnd = now.minusMonths(i)\n362\t                    .withDayOfMonth(now.minusMonths(i).lengthOfMonth());\n363\t            LocalDateTime monthEndDateTime = monthEnd.atTime(23, 59, 59);\n364\t\n365\t            // Delegate counting to the database — zero heap allocation for entity graphs\n366\t            long tenantCount = tenantRepository.countByCreatedAtBefore(monthEndDateTime);\n367\t            long employeeCount = employeeRepository.countJoinedOnOrBefore(monthEnd, monthEndDateTime);\n368\t            long activeUserCount = userRepository.countByStatusAndCreatedAtBefore(\n369\t                    User.UserStatus.ACTIVE, monthEndDateTime);\n370\t\n371\t            Month month = monthEnd.getMonth();\n372\t            growthList.add(GrowthMetricsDTO.MonthlyGrowth.builder()\n373\t                    .month(month.getDisplayName(TextStyle.SHORT, Locale.ENGLISH))\n374\t                    .year(monthEnd.getYear())\n375\t                    .tenants(tenantCount)\n376\t                    .activeUsers(activeUserCount)\n377\t                    .employees(employeeCount)\n378\t                    .build());\n379\t        }\n380\t\n381\t        return GrowthMetricsDTO.builder().months(growthList).build();\n382\t    }\n383\t\n384\t    /**\n385\t     * Suspend a tenant — immediately revokes access by invalidating all caches.\n386\t     *\n387\t     * <p>This method performs three cache-invalidation steps to ensure the suspended\n388\t     * tenant cannot continue making requests:\n389\t     * <ol>\n390\t     *   <li>Persist the status change to the database.</li>\n391\t     *   <li>Remove the tenant from {@link TenantFilter}'s in-memory valid-tenant cache\n392\t     *       so subsequent requests are rejected immediately (SEC-B10).</li>\n393\t     *   <li>Flush all Redis caches scoped to the tenant via {@link TenantCacheManager}\n394\t     *       to prevent stale data from being served.</li>\n395\t     * </ol>\n396\t     */\n397\t    @Transactional\n398\t    public Tenant suspendTenant(UUID tenantId) {\n399\t        log.info(\"SuperAdmin suspending tenant: {}\", tenantId);\n400\t\n401\t        Tenant tenant = tenantRepository.findById(tenantId)\n402\t                .orElseThrow(() -> new ResourceNotFoundException(\"Tenant not found with ID: \" + tenantId));\n403\t\n404\t        tenant.suspend(); // throws IllegalStateException if not ACTIVE\n405\t        tenantRepository.save(tenant);\n406\t\n407\t        // Immediately invalidate caches so the tenant is locked out (SEC-B10)\n408\t        tenantFilter.invalidateTenant(tenantId);\n409\t        tenantCacheManager.invalidateTenantCaches(tenantId);\n410\t        // Sprint-4 follow-up: bypass the 30-second TenantStatusCache TTL so the\n411\t        // JwtAuthenticationFilter sees the SUSPENDED status on the very next request.\n412\t        tenantStatusCache.evict(tenantId);\n413\t        // Sprint-4 M-C4: drop a tenant-wide revocation marker so any token already in flight\n414\t        // for users of this tenant is treated as revoked. The primary defense remains the\n415\t        // JWT-filter tenant-status check; this is belt-and-braces for race windows where a\n416\t        // token was minted just before suspension.\n417\t        tokenBlacklistService.revokeAllTokensForTenant(tenantId, Instant.now());\n418\t\n419\t        // Audit log the suspension\n420\t        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();\n421\t        auditLogService.logAction(\n422\t                \"TENANT\",\n423\t                tenantId,\n424\t                com.nulogic.domain.audit.AuditLog.AuditAction.UPDATE,\n425\t                Map.of(\"previousStatus\", \"ACTIVE\", \"newStatus\", \"SUSPENDED\"),\n426\t                Map.of(\"admin_user_id\", currentUserId),\n427\t                \"SuperAdmin suspended tenant: \" + tenant.getName()\n428\t        );\n429\t\n430\t        log.info(\"Tenant {} suspended successfully. Caches invalidated.\", tenantId);\n431\t        return tenant;\n432\t    }\n433\t\n434\t    /**\n435\t     * Re-activate a previously suspended tenant.\n436\t     */\n437\t    @Transactional\n438\t    public Tenant activateTenant(UUID tenantId) {\n439\t        log.info(\"SuperAdmin activating tenant: {}\", tenantId);\n440\t\n441\t        Tenant tenant = tenantRepository.findById(tenantId)\n442\t                .orElseThrow(() -> new ResourceNotFoundException(\"Tenant not found with ID: \" + tenantId));\n443\t\n444\t        String previousStatus = tenant.getStatus().name();\n445\t        tenant.activate(); // throws IllegalStateException if not SUSPENDED/PENDING_ACTIVATION\n446\t        tenantRepository.save(tenant);\n447\t        // Sprint-4 follow-up: bypass the 30-second TenantStatusCache TTL so users of this\n448\t        // tenant regain access on the very next request instead of waiting for TTL expiry.\n449\t        tenantStatusCache.evict(tenantId);\n450\t\n451\t        // Audit log the activation\n452\t        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();\n453\t        auditLogService.logAction(\n454\t                \"TENANT\",\n455\t                tenantId,\n456\t                com.nulogic.domain.audit.AuditLog.AuditAction.UPDATE,\n457\t                Map.of(\"previousStatus\", previousStatus, \"newStatus\", \"ACTIVE\"),\n458\t                Map.of(\"admin_user_id\", currentUserId),\n459\t                \"SuperAdmin activated tenant: \" + tenant.getName()\n460\t        );\n461\t\n462\t        log.info(\"Tenant {} activated successfully.\", tenantId);\n463\t        return tenant;\n464\t    }\n465\t\n466\t    /**\n467\t     * Update the IANA timezone for a tenant and invalidate the per-tenant {@link ZoneId}\n468\t     * cache in {@link TenantTimeService} so the change takes effect within the JVM without\n469\t     * waiting for the 1-hour cache TTL.\n470\t     *\n471\t     * <p><strong>Why invalidate AFTER commit.</strong> If we invalidated before the\n472\t     * transaction commits, a parallel request could:\n473\t     * <ol>\n474\t     *   <li>see the invalidation,</li>\n475\t     *   <li>call {@code zoneFor(tenantId)} which DB-reads the <em>old</em> timezone (the\n476\t     *       update isn't visible to another connection until commit), and</li>\n477\t     *   <li>repopulate the cache with the stale value — leaving us right back where we\n478\t     *       started for up to another TTL window.</li>\n479\t     * </ol>\n480\t     * Deferring to {@code afterCommit} closes that race: by the time the cache is cleared,\n481\t     * any subsequent read will see the new row. If the transaction rolls back, the cache\n482\t     * is left untouched (correct — the DB value didn't change).</p>\n483\t     *\n484\t     * <p><strong>Multi-pod caveat.</strong> This invalidates only the local JVM cache.\n485\t     * Other pods will continue serving the old zone for up to 1 hour. That is acceptable\n486\t     * for admin-triggered changes (rare, plannable) per the wave-10 audit. If we need\n487\t     * cross-pod immediate consistency we should publish a Redis pub/sub event and have\n488\t     * each pod subscribe — out of scope here.</p>\n489\t     *\n490\t     * @param tenantId target tenant\n491\t     * @param newTimezone IANA zone-id; must match the V165 regex (already enforced at\n492\t     *                    the controller boundary, re-validated here as defence-in-depth)\n493\t     * @return the updated tenant\n494\t     */\n495\t    @Transactional\n496\t    public Tenant updateTenantTimezone(UUID tenantId, String newTimezone) {\n497\t        log.info(\"SuperAdmin updating timezone for tenant {} to '{}'\", tenantId, newTimezone);\n498\t\n499\t        if (newTimezone == null || newTimezone.isBlank()) {\n500\t            throw new ValidationException(\"Timezone is required\");\n501\t        }\n502\t\n503\t        // Semantic validation — the regex at the controller checks shape, but only ZoneId.of\n504\t        // can tell us whether the string is a known zone-id. Better to fail here with a clear\n505\t        // error than to write a row that TenantTimeService will silently fall back from.\n506\t        try {\n507\t            ZoneId.of(newTimezone);\n508\t        } catch (DateTimeException e) {\n509\t            throw new ValidationException(\"Unknown IANA timezone: '\" + newTimezone + \"'\");\n510\t        }\n511\t\n512\t        Tenant tenant = tenantRepository.findById(tenantId)\n513\t                .orElseThrow(() -> new ResourceNotFoundException(\"Tenant not found with ID: \" + tenantId));\n514\t\n515\t        String previousTimezone = tenant.getTimezone();\n516\t        if (newTimezone.equals(previousTimezone)) {\n517\t            log.info(\"Tenant {} timezone already '{}' — no-op\", tenantId, newTimezone);\n518\t            return tenant;\n519\t        }\n520\t\n521\t        tenant.setTimezone(newTimezone);\n522\t        tenantRepository.save(tenant);\n523\t\n524\t        // Defer cache invalidation to afterCommit so a concurrent read cannot repopulate\n525\t        // the cache with the pre-commit (stale) value. Mirrors the DomainEventPublisher\n526\t        // pattern used elsewhere in the codebase.\n527\t        if (TransactionSynchronizationManager.isActualTransactionActive()) {\n528\t            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {\n529\t                @Override\n530\t                public void afterCommit() {\n531\t                    tenantTimeService.invalidate(tenantId);\n532\t                    log.info(\"TenantTimeService cache invalidated for tenant {} after timezone commit\", tenantId);\n533\t                }\n534\t            });\n535\t        } else {\n536\t            // Defensive branch — @Transactional on this method guarantees a tx is active,\n537\t            // but if a caller ever bypasses the proxy (e.g. self-invocation, test setup),\n538\t            // invalidate inline so behaviour is still correct.\n539\t            tenantTimeService.invalidate(tenantId);\n540\t        }\n541\t\n542\t        // Audit log the timezone change\n543\t        UUID currentUserId = com.nulogic.common.security.SecurityContext.getCurrentUserId();\n544\t        auditLogService.logAction(\n545\t                \"TENANT\",\n546\t                tenantId,\n547\t                com.nulogic.domain.audit.AuditLog.AuditAction.UPDATE,\n548\t                Map.of(\"previousTimezone\", previousTimezone == null ? \"\" : previousTimezone,\n549\t                        \"newTimezone\", newTimezone),\n550\t                Map.of(\"admin_user_id\", currentUserId == null ? \"\" : currentUserId.toString()),\n551\t                \"SuperAdmin updated timezone for tenant: \" + tenant.getName()\n552\t        );\n553\t\n554\t        log.info(\"Tenant {} timezone updated from '{}' to '{}'\", tenantId, previousTimezone, newTimezone);\n555\t        return tenant;\n556\t    }\n557\t\n558\t    // ===================== Helper Methods =====================\n559\t\n560\t    private long countActiveTenants() {\n561\t        return tenantRepository.countByStatus(Tenant.TenantStatus.ACTIVE);\n562\t    }\n563\t\n564\t    private long countActiveUsers() {\n565\t        // Single aggregate query — no longer loads all users into memory\n566\t        return userRepository.countByStatus(User.UserStatus.ACTIVE);\n567\t    }\n568\t\n569\t    private long countActiveUsersForTenant(UUID tenantId) {\n570\t        // Delegate to batch query map entry — avoids loading all tenant users into memory\n571\t        return userRepository.countActiveByTenantIdIn(List.of(tenantId))\n572\t                .stream()\n573\t                .filter(r -> tenantId.equals(r[0]))\n574\t                .map(r -> (Long) r[1])\n575\t                .findFirst()\n576\t                .orElse(0L);\n577\t    }\n578\t\n579\t    private long countUsersForTenant(UUID tenantId) {\n580\t        return userRepository.countByTenantId(tenantId);\n581\t    }\n582\t\n583\t    private long countEmployeesForTenant(UUID tenantId) {\n584\t        return employeeRepository.countByTenantId(tenantId);\n585\t    }\n586\t\n587\t    private long countPendingApprovals() {\n588\t        // Single cross-tenant query replaces the previous 2N+1 queries per tenant (N+1 fix)\n589\t        try {\n590\t            return workflowExecutionRepository.countAllPendingCrossTenant();\n591\t        } catch (Exception e) { // Intentional broad catch — admin operation error boundary\n592\t            log.warn(\"Could not count pending approvals: {}\", e.getMessage());\n593\t            return 0L;\n594\t        }\n595\t    }\n596\t\n597\t    private long countPendingApprovalsForTenant(UUID tenantId) {\n598\t        long count = 0;\n599\t        try {\n600\t            count += workflowExecutionRepository.countByStatus(\n601\t                    tenantId,\n602\t                    WorkflowExecution.ExecutionStatus.PENDING\n603\t            );\n604\t            count += workflowExecutionRepository.countByStatus(\n605\t                    tenantId,\n606\t                    WorkflowExecution.ExecutionStatus.IN_PROGRESS\n607\t            );\n608\t        } catch (Exception e) { // Intentional broad catch — admin operation error boundary\n609\t            log.warn(\"Could not count pending approvals for tenant {}: {}\", tenantId, e.getMessage());\n610\t        }\n611\t        return count;\n612\t    }\n613\t\n614\t    private LocalDateTime getLastActivityForTenant(UUID tenantId) {\n615\t        // Query the database for the maximum lastLoginAt timestamp for the tenant.\n616\t        // This avoids loading all users into the Java heap and streaming them.\n617\t        return userRepository.findMaxLastLoginAtByTenantId(tenantId).orElse(null);\n618\t    }\n619\t\n620\t    /**\n621\t     * SuperAdmin-initiated password reset.\n622\t     *\n623\t     * <p>Sequence:\n624\t     * <ol>\n625\t     *   <li>Resolve the target user inside the current tenant scope (defence-in-depth — even\n626\t     *       though {@code SYSTEM_ADMIN} bypasses tenant filters at the security layer, we\n627\t     *       still pin the lookup to {@link TenantContext} so cross-tenant accidents require\n628\t     *       an explicit impersonation token first).</li>\n629\t     *   <li>Generate a 12-char URL-safe Base64 temp password from {@link SecureRandom}.</li>\n630\t     *   <li>Persist the BCrypt-encoded hash and stamp {@code passwordChangedAt} so existing\n631\t     *       password-age policies kick in.</li>\n632\t     *   <li>Revoke all in-flight JWTs for the user via\n633\t     *       {@link TokenBlacklistService#revokeAllTokensBefore(String, Instant)}.</li>\n634\t     *   <li>Write an audit-log entry (action = {@code PASSWORD_CHANGE}; the enum has no\n635\t     *       dedicated {@code PASSWORD_RESET} value — extend the enum in a follow-up if a\n636\t     *       distinct event type is required).</li>\n637\t     *   <li>Send the temp password to the user out-of-band via email.</li>\n638\t     * </ol></p>\n639\t     *\n640\t     * <p><strong>Security:</strong> the returned DTO never contains the temp password.</p>\n641\t     */\n642\t    @Transactional\n643\t    public AdminPasswordResetResponse adminResetPassword(AdminPasswordResetRequest request, UUID adminUserId) {\n644\t        UUID currentTenant = TenantContext.getCurrentTenant();\n645\t        log.info(\"SuperAdmin {} initiating password reset for user {} in tenant {}\",\n646\t                adminUserId, request.getUserId(), currentTenant);\n647\t\n648\t        User user = userRepository.findByIdAndTenantId(request.getUserId(), currentTenant)\n649\t                .orElseThrow(() -> new BusinessException(\"User not found\"));\n650\t\n651\t        String tempPassword = generateSecureTempPassword();\n652\t        user.setPasswordHash(passwordEncoder.encode(tempPassword));\n653\t        user.setPasswordChangedAt(tenantTimeService.now(currentTenant));\n654\t        userRepository.save(user);\n655\t\n656\t        // Revoke all outstanding JWTs for this user so the old password can't be used post-reset.\n657\t        // The marker key is the userId; signature requires String, hence toString().\n658\t        tokenBlacklistService.revokeAllTokensBefore(user.getId().toString(), Instant.now());\n659\t\n660\t        // Audit log — using PASSWORD_CHANGE because AuditAction.PASSWORD_RESET does not exist\n661\t        // in the enum. If a distinct event type is needed downstream, extend AuditLog.AuditAction\n662\t        // in a follow-up sprint (out of scope here — the audit domain belongs to another owner).\n663\t        auditLogService.logAction(\n664\t                \"USER\",\n665\t                user.getId(),\n666\t                AuditLog.AuditAction.PASSWORD_CHANGE,\n667\t                null,\n668\t                null,\n669\t                \"Admin reset by \" + adminUserId + \": \" + request.getReason()\n670\t        );\n671\t\n672\t        // TODO(S6-B-followup): add EmailNotificationService#sendAdminPasswordReset(User, String)\n673\t        //   that uses a dedicated \"admin-initiated reset\" template explaining the rotation cause.\n674\t        //   Method signature:\n675\t        //     public void sendAdminPasswordReset(User user, String tempPassword)\n676\t        //   For now we reuse the generic password-reset template — the user receives the temp\n677\t        //   credential in the token slot so they can sign in once and immediately rotate.\n678\t        emailNotificationService.sendPasswordResetEmail(\n679\t                user.getEmail(),\n680\t                user.getFirstName() != null ? user.getFirstName() : user.getEmail(),\n681\t                tempPassword\n682\t        );\n683\t\n684\t        LocalDateTime resetAt = tenantTimeService.now(currentTenant);\n685\t        log.info(\"Password reset completed for user {} by admin {} at {}\",\n686\t                user.getId(), adminUserId, resetAt);\n687\t\n688\t        return AdminPasswordResetResponse.builder()\n689\t                .success(true)\n690\t                .userId(user.getId())\n691\t                .resetAt(resetAt)\n692\t                .mustChange(true)\n693\t                .build();\n694\t    }\n695\t\n696\t    /**\n697\t     * Generate a 12-character URL-safe Base64 temp password from 9 random bytes\n698\t     * (9 bytes × 8 bits = 72 bits of entropy, encoded as 12 Base64 chars without padding).\n699\t     */\n700\t    private String generateSecureTempPassword() {\n701\t        byte[] bytes = new byte[9];\n702\t        SECURE_RANDOM.nextBytes(bytes);\n703\t        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);\n704\t    }\n705\t\n706\t    /**\n707\t     * Map a Tenant to TenantListItemDTO using pre-fetched batch counts (N+1 fix).\n708\t     */\n709\t    private TenantListItemDTO mapToTenantListItem(Tenant tenant, long employeeCount, long userCount,\n710\t                                                  LocalDateTime lastActivityAt) {\n711\t        long storageUsageBytes = storageMetricsService.getStorageBytesForTenant(tenant.getId());\n712\t\n713\t        return TenantListItemDTO.builder()\n714\t                .tenantId(tenant.getId())\n715\t                .name(tenant.getName())\n716\t                .plan(\"STANDARD\") // Default plan, can be extended in future\n717\t                .status(tenant.getStatus() != null ? tenant.getStatus().name() : \"ACTIVE\")\n718\t                .employeeCount(employeeCount)\n719\t                .userCount(userCount)\n720\t                .storageUsageBytes(storageUsageBytes)\n721\t                .createdAt(tenant.getCreatedAt())\n722\t                .lastActivityAt(lastActivityAt)\n723\t                .build();\n724\t    }\n725\t}\n726\t"}]},"parent_tool_use_id":"toolu_01JgAM9Ax18NS4WRFCdnZTFn","session_id":"61db98fd-c720-4414-89bd-2708d1298a20","uuid":"f15b42ab-9ac2-478a-a110-0b09b0e8b6d4","timestamp":"2026-06-11T19:26:22.544Z","subagent_type":"Explore","task_description":"Explore audit search endpoint+tests"}
{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01XPb66eAHEVoLog7aDYtVBc","type":"tool_result","content":"1\tpackage com.nulogic.api.admin.controller;\n2\t\n3\timport com.nulogic.api.audit.dto.AuditLogResponse;\n4\timport com.nulogic.application.audit.service.AuditLogService;\n5\timport com.nulogic.common.security.RequiresPermission;\n6\timport com.nulogic.domain.audit.AuditLog.AuditAction;\n7\timport io.swagger.v3.oas.annotations.Operation;\n8\timport io.swagger.v3.oas.annotations.Parameter;\n9\timport io.swagger.v3.oas.annotations.tags.Tag;\n10\timport lombok.RequiredArgsConstructor;\n11\timport lombok.extern.slf4j.Slf4j;\n12\timport org.springframework.data.domain.Page;\n13\timport org.springframework.data.domain.Pageable;\n14\timport org.springframework.data.web.PageableDefault;\n15\timport org.springframework.format.annotation.DateTimeFormat;\n16\timport org.springframework.web.bind.annotation.GetMapping;\n17\timport org.springframework.web.bind.annotation.RequestMapping;\n18\timport org.springframework.web.bind.annotation.RequestParam;\n19\timport org.springframework.web.bind.annotation.RestController;\n20\t\n21\timport java.time.LocalDateTime;\n22\timport java.util.UUID;\n23\t\n24\timport static com.nulogic.common.security.Permission.SYSTEM_ADMIN;\n25\t\n26\t/**\n27\t * SuperAdmin cross-tenant audit-log inspection endpoint (wave-3 M-C2).\n28\t *\n29\t * <p>All endpoints require the {@code SYSTEM:ADMIN} permission with {@code revalidate=true}\n30\t * so every request re-reads the user's current role from the database — stale JWT claims\n31\t * cannot grant cross-tenant audit visibility. The service layer re-checks the same gate\n32\t * for defense-in-depth.</p>\n33\t *\n34\t * <p>Distinct from the tenant-scoped {@code AuditLogController} which is filtered by\n35\t * {@link com.nulogic.common.security.TenantContext}.</p>\n36\t */\n37\t@RestController\n38\t@RequestMapping(\"/api/v1/admin/system/audit-logs\")\n39\t@RequiredArgsConstructor\n40\t@Slf4j\n41\t@Tag(name = \"System Audit Logs\", description = \"SuperAdmin cross-tenant audit log inspection\")\n42\tpublic class SystemAuditLogController {\n43\t\n44\t    private final AuditLogService auditLogService;\n45\t\n46\t    /**\n47\t     * List audit logs across all tenants, paginated. Ordered by createdAt DESC.\n48\t     */\n49\t    @GetMapping\n50\t    @Operation(summary = \"Get all audit logs (cross-tenant)\",\n51\t            description = \"Returns paginated audit logs across all tenants. SuperAdmin only.\")\n52\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n53\t    public Page<AuditLogResponse> getAllAuditLogsCrossTenant(\n54\t            @PageableDefault(size = 50, page = 0) Pageable pageable) {\n55\t        log.info(\"SuperAdmin requesting cross-tenant audit logs, page: {}, size: {}\",\n56\t                pageable.getPageNumber(), pageable.getPageSize());\n57\t        return auditLogService.getAllAuditLogsCrossTenant(pageable);\n58\t    }\n59\t\n60\t    /**\n61\t     * Search audit logs across tenants with optional filters. When {@code tenantId}\n62\t     * is omitted the search spans all tenants; otherwise it narrows to a single tenant.\n63\t     */\n64\t    @GetMapping(\"/search\")\n65\t    @Operation(summary = \"Search audit logs (cross-tenant)\",\n66\t            description = \"Searches audit logs across tenants. Pass tenantId to narrow to a single tenant, \" +\n67\t                    \"omit it to search the whole system. SuperAdmin only.\")\n68\t    @RequiresPermission(value = SYSTEM_ADMIN, revalidate = true)\n69\t    public Page<AuditLogResponse> searchCrossTenant(\n70\t            @Parameter(description = \"Optional tenant ID to narrow the search\")\n71\t            @RequestParam(required = false) UUID tenantId,\n72\t            @Parameter(description = \"Optional entity-type filter (e.g. USER, TENANT)\")\n73\t            @RequestParam(required = false) String entityType,\n74\t            @Parameter(description = \"Optional audit-action filter\")\n75\t            @RequestParam(required = false) AuditAction action,\n76\t            @Parameter(description = \"Optional actor user-ID filter\")\n77\t            @RequestParam(required = false) UUID actorId,\n78\t            @Parameter(description = \"Lower bound on createdAt (ISO-8601 date-time)\")\n79\t            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) LocalDateTime startDate,\n80\t            @Parameter(description = \"Upper bound on createdAt (ISO-8601 date-time)\")\n81\t            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) LocalDateTime endDate,\n82\t            @PageableDefault(size = 50, page = 0) Pageable pageable) {\n83\t        log.info(\"SuperAdmin searching cross-tenant audit logs (tenantId={}, entityType={}, action={})\",\n84\t                tenantId, entityType, action);\n85\t        return auditLogService.searchCrossTenant(tenantId, entityType, action, actorId, startDate, endDate, pageable);\n86\t    }\n87\t}\n88\t"}]},"parent_tool_use_id":"toolu_01JgAM9Ax18NS4WRFCdnZTFn","session_id":"61db98fd-c720-4414-89bd-2708d1298a20","uuid":"4ea668c7-8e18-41bc-81ab-b1380fcb3a18","timestamp":"2026-06-11T19:26:22.515Z","subagent_type":"Explore","task_description":"Explore audit search endpoint+tests"}
