{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_018hYmukNvNSg38LDhAFsA9X","type":"tool_result","content":"1\tpackage com.nulogic.application.audit.service;\n2\t\n3\timport com.fasterxml.jackson.core.JsonProcessingException;\n4\timport com.fasterxml.jackson.databind.ObjectMapper;\n5\timport com.nulogic.api.audit.dto.AuditLogResponse;\n6\timport com.nulogic.api.audit.dto.AuditStatisticsResponse;\n7\timport com.nulogic.common.security.SecurityContext;\n8\timport com.nulogic.common.security.TenantContext;\n9\timport com.nulogic.common.util.TenantTimeService;\n10\timport com.nulogic.domain.audit.AuditLog;\n11\timport com.nulogic.domain.audit.AuditLog.AuditAction;\n12\timport com.nulogic.infrastructure.audit.repository.AuditLogRepository;\n13\timport com.nulogic.infrastructure.employee.repository.EmployeeRepository;\n14\timport jakarta.servlet.http.HttpServletRequest;\n15\timport lombok.RequiredArgsConstructor;\n16\timport lombok.extern.slf4j.Slf4j;\n17\timport org.springframework.data.domain.Page;\n18\timport org.springframework.data.domain.PageRequest;\n19\timport org.springframework.data.domain.Pageable;\n20\timport org.springframework.data.domain.Sort;\n21\timport org.springframework.scheduling.annotation.Async;\n22\timport org.springframework.security.access.AccessDeniedException;\n23\timport org.springframework.stereotype.Service;\n24\timport org.springframework.transaction.annotation.Propagation;\n25\timport org.springframework.transaction.annotation.Transactional;\n26\timport org.springframework.web.context.request.RequestContextHolder;\n27\timport org.springframework.web.context.request.ServletRequestAttributes;\n28\t\n29\timport java.time.LocalDateTime;\n30\timport java.util.*;\n31\timport java.util.stream.Collectors;\n32\t\n33\t@Service\n34\t@RequiredArgsConstructor\n35\t@Slf4j\n36\tpublic class AuditLogService {\n37\t\n38\t    private final AuditLogRepository auditLogRepository;\n39\t    private final EmployeeRepository employeeRepository;\n40\t    private final ObjectMapper objectMapper;\n41\t    private final TenantTimeService tenantTimeService;\n42\t\n43\t    // ==================== Logging Methods ====================\n44\t\n45\t    /**\n46\t     * Asynchronous, isolated audit write — runs in its own REQUIRES_NEW transaction\n47\t     * so an audit failure cannot poison the caller's business transaction, and audit\n48\t     * persistence happens off the request thread (Q-P19).\n49\t     *\n50\t     * <p>Return type is {@code void} because no caller consumes the return value and\n51\t     * {@code @Async} requires void or {@code Future<>}. Resolution: any failure is\n52\t     * logged but not propagated.</p>\n53\t     */\n54\t    @Async\n55\t    @Transactional(propagation = Propagation.REQUIRES_NEW)\n56\t    public void logAction(\n57\t            String entityType,\n58\t            UUID entityId,\n59\t            AuditAction action,\n60\t            Object oldValue,\n61\t            Object newValue,\n62\t            String description\n63\t    ) {\n64\t        try {\n65\t            UUID actorId = SecurityContext.getCurrentUserId();\n66\t\n67\t            // FIX (wave-3 2.3): {@link TenantAwareTaskDecorator} now snapshots\n68\t            // RequestAttributes from the calling thread and re-attaches them on\n69\t            // this @Async worker thread, so {@link #getHttpServletRequest()}\n70\t            // returns the originating request rather than null. If you remove\n71\t            // that decorator, IP/User-Agent capture here will silently break —\n72\t            // see {@code AsyncConfig#getAsyncExecutor()}.\n73\t            HttpServletRequest request = getHttpServletRequest();\n74\t            String ipAddress = request != null ? getClientIp(request) : null;\n75\t            String userAgent = request != null ? request.getHeader(\"User-Agent\") : null;\n76\t\n77\t            UUID tenantId = SecurityContext.getCurrentTenantId();\n78\t\n79\t            AuditLog auditLog = AuditLog.builder()\n80\t                    .entityType(entityType)\n81\t                    .entityId(entityId)\n82\t                    .action(action)\n83\t                    .actorId(actorId)\n84\t                    .actorEmail(null)\n85\t                    .oldValue(oldValue != null ? objectMapper.writeValueAsString(oldValue) : null)\n86\t                    .newValue(newValue != null ? objectMapper.writeValueAsString(newValue) : null)\n87\t                    .changes(description)\n88\t                    .ipAddress(ipAddress)\n89\t                    .userAgent(userAgent != null && userAgent.length() > 500 ? userAgent.substring(0, 500) : userAgent)\n90\t                    .build();\n91\t\n92\t            auditLog.setTenantId(tenantId);\n93\t\n94\t            // Audit M-C3 / M-M5 wave-3: when SuperAdmin acts on behalf of a tenant user,\n95\t            // capture the underlying admin so the audit chain records both principals.\n96\t            // Field + SecurityContext accessor were added in sprint 2 (agent H).\n97\t            UUID impersonatorId = SecurityContext.getCurrentImpersonatorId();\n98\t            if (impersonatorId != null) {\n99\t                auditLog.setImpersonatorId(impersonatorId);\n100\t            }\n101\t\n102\t            auditLogRepository.save(auditLog);\n103\t        } catch (JsonProcessingException e) {\n104\t            log.error(\"Failed to serialize audit log values\", e);\n105\t        }\n106\t    }\n107\t\n108\t    @Async\n109\t    @Transactional(propagation = Propagation.REQUIRES_NEW)\n110\t    public void logAction(String entityType, UUID entityId, AuditAction action) {\n111\t        logAction(entityType, entityId, action, null, null, null);\n112\t    }\n113\t\n114\t    @Async\n115\t    @Transactional(propagation = Propagation.REQUIRES_NEW)\n116\t    public void logSecurityEvent(AuditAction action, UUID userId, String description) {\n117\t        logAction(\"USER\", userId, action, null, null, description);\n118\t    }\n119\t\n120\t    // ==================== Query Methods (Tenant-Aware) ====================\n121\t\n122\t    @Transactional(readOnly = true)\n123\t    public Page<AuditLogResponse> getAllAuditLogs(Pageable pageable) {\n124\t        UUID tenantId = TenantContext.getCurrentTenant();\n125\t        return auditLogRepository.findAllByTenantIdOrderByCreatedAtDesc(tenantId, pageable)\n126\t                .map(this::enrichResponse);\n127\t    }\n128\t\n129\t    @Transactional(readOnly = true)\n130\t    public Page<AuditLogResponse> searchAuditLogs(\n131\t            String entityType,\n132\t            AuditAction action,\n133\t            UUID actorId,\n134\t            LocalDateTime startDate,\n135\t            LocalDateTime endDate,\n136\t            Pageable pageable) {\n137\t        UUID tenantId = TenantContext.getCurrentTenant();\n138\t        return auditLogRepository.searchAuditLogs(tenantId, entityType, action, actorId, startDate, endDate, pageable)\n139\t                .map(this::enrichResponse);\n140\t    }\n141\t\n142\t    @Transactional(readOnly = true)\n143\t    public Page<AuditLogResponse> getAuditLogsByEntityType(String entityType, Pageable pageable) {\n144\t        UUID tenantId = TenantContext.getCurrentTenant();\n145\t        return auditLogRepository.findByTenantIdAndEntityTypeOrderByCreatedAtDesc(tenantId, entityType, pageable)\n146\t                .map(this::enrichResponse);\n147\t    }\n148\t\n149\t    @Transactional(readOnly = true)\n150\t    public Page<AuditLogResponse> getAuditLogsByEntity(String entityType, UUID entityId, Pageable pageable) {\n151\t        UUID tenantId = TenantContext.getCurrentTenant();\n152\t        return auditLogRepository.findByTenantIdAndEntityTypeAndEntityIdOrderByCreatedAtDesc(tenantId, entityType, entityId, pageable)\n153\t                .map(this::enrichResponse);\n154\t    }\n155\t\n156\t    @Transactional(readOnly = true)\n157\t    public Page<AuditLogResponse> getAuditLogsByActor(UUID actorId, Pageable pageable) {\n158\t        UUID tenantId = TenantContext.getCurrentTenant();\n159\t        return auditLogRepository.findByTenantIdAndActorIdOrderByCreatedAtDesc(tenantId, actorId, pageable)\n160\t                .map(this::enrichResponse);\n161\t    }\n162\t\n163\t    @Transactional(readOnly = true)\n164\t    public Page<AuditLogResponse> getAuditLogsByAction(AuditAction action, Pageable pageable) {\n165\t        UUID tenantId = TenantContext.getCurrentTenant();\n166\t        return auditLogRepository.findByTenantIdAndActionOrderByCreatedAtDesc(tenantId, action, pageable)\n167\t                .map(this::enrichResponse);\n168\t    }\n169\t\n170\t    @Transactional(readOnly = true)\n171\t    public Page<AuditLogResponse> getAuditLogsByDateRange(LocalDateTime startDate, LocalDateTime endDate, Pageable pageable) {\n172\t        UUID tenantId = TenantContext.getCurrentTenant();\n173\t        return auditLogRepository.findByTenantIdAndDateRange(tenantId, startDate, endDate, pageable)\n174\t                .map(this::enrichResponse);\n175\t    }\n176\t\n177\t    @Transactional(readOnly = true)\n178\t    public Page<AuditLogResponse> getSecurityEvents(LocalDateTime startDate, LocalDateTime endDate, Pageable pageable) {\n179\t        UUID tenantId = TenantContext.getCurrentTenant();\n180\t        return auditLogRepository.findSecurityEvents(tenantId, startDate, endDate, pageable)\n181\t                .map(this::enrichResponse);\n182\t    }\n183\t\n184\t    @Transactional(readOnly = true)\n185\t    public List<AuditLogResponse> getRecentAuditLogsForEntity(String entityType, UUID entityId) {\n186\t        UUID tenantId = TenantContext.getCurrentTenant();\n187\t        return auditLogRepository.findTop10ByTenantIdAndEntityTypeAndEntityIdOrderByCreatedAtDesc(tenantId, entityType, entityId)\n188\t                .stream()\n189\t                .map(this::enrichResponse)\n190\t                .collect(Collectors.toList());\n191\t    }\n192\t\n193\t    // ==================== Cross-Tenant Query Methods (SUPER_ADMIN only — wave-3 M-C2) ====================\n194\t\n195\t    /**\n196\t     * Cross-tenant audit-log query for SuperAdmin / SYSTEM:ADMIN.\n197\t     *\n198\t     * <p><strong>Security:</strong> intentionally bypasses {@link TenantContext}'s\n199\t     * tenant filter. The caller-side controller already gates entry via\n200\t     * {@code @RequiresPermission(SYSTEM_ADMIN, revalidate=true)}; we re-check here\n201\t     * for defense-in-depth so a misconfigured controller cannot accidentally expose\n202\t     * cross-tenant audit data.</p>\n203\t     */\n204\t    @Transactional(readOnly = true)\n205\t    public Page<AuditLogResponse> getAllAuditLogsCrossTenant(Pageable pageable) {\n206\t        requireSuperAdminOrSystemAdmin();\n207\t        return auditLogRepository.findAllByOrderByCreatedAtDesc(pageable)\n208\t                .map(this::enrichResponseCrossTenant);\n209\t    }\n210\t\n211\t    /**\n212\t     * Cross-tenant search with optional {@code tenantId} narrowing for SuperAdmin.\n213\t     * When {@code tenantId} is null, the search spans all tenants.\n214\t     */\n215\t    @Transactional(readOnly = true)\n216\t    public Page<AuditLogResponse> searchCrossTenant(UUID tenantId, String entityType, AuditAction action,\n217\t                                                    UUID actorId, LocalDateTime startDate, LocalDateTime endDate,\n218\t                                                    Pageable pageable) {\n219\t        requireSuperAdminOrSystemAdmin();\n220\t        return auditLogRepository.searchCrossTenant(tenantId, entityType, action, actorId, startDate, endDate, pageable)\n221\t                .map(this::enrichResponseCrossTenant);\n222\t    }\n223\t\n224\t    /**\n225\t     * Defense-in-depth re-check that the current security context holds SUPER_ADMIN\n226\t     * role or the SYSTEM:ADMIN permission. Throws {@link AccessDeniedException}\n227\t     * (handled by the global exception handler -> 403) when neither is present.\n228\t     */\n229\t    private void requireSuperAdminOrSystemAdmin() {\n230\t        if (!SecurityContext.isSuperAdmin() && !SecurityContext.hasPermission(\"SYSTEM:ADMIN\")) {\n231\t            throw new AccessDeniedException(\n232\t                    \"Cross-tenant audit-log query requires SUPER_ADMIN or SYSTEM:ADMIN\");\n233\t        }\n234\t    }\n235\t\n236\t    /**\n237\t     * Cross-tenant variant of {@link #enrichResponse(AuditLog)} — uses the audit\n238\t     * log's own tenantId rather than {@link TenantContext}, so actor-name enrichment\n239\t     * works correctly when the result spans many tenants.\n240\t     */\n241\t    private AuditLogResponse enrichResponseCrossTenant(AuditLog entity) {\n242\t        AuditLogResponse response = AuditLogResponse.fromEntity(entity);\n243\t        if (entity.getActorId() != null && entity.getTenantId() != null) {\n244\t            employeeRepository.findByIdAndTenantId(entity.getActorId(), entity.getTenantId())\n245\t                    .ifPresent(emp -> response.setActorName(emp.getFirstName() + \" \" + emp.getLastName()));\n246\t        }\n247\t        return response;\n248\t    }\n249\t\n250\t    // ==================== Statistics Methods ====================\n251\t\n252\t    @Transactional(readOnly = true)\n253\t    public AuditStatisticsResponse getAuditStatistics(LocalDateTime startDate, LocalDateTime endDate) {\n254\t        UUID tenantId = TenantContext.getCurrentTenant();\n255\t\n256\t        long totalEvents = auditLogRepository.countByTenantIdAndDateRange(tenantId, startDate, endDate);\n257\t\n258\t        // Events by action\n259\t        Map<String, Long> eventsByAction = new LinkedHashMap<>();\n260\t        List<Object[]> actionCounts = auditLogRepository.countByActionForDateRange(tenantId, startDate, endDate);\n261\t        for (Object[] row : actionCounts) {\n262\t            AuditAction action = (AuditAction) row[0];\n263\t            Long count = (Long) row[1];\n264\t            eventsByAction.put(action.name(), count);\n265\t        }\n266\t\n267\t        // Events by entity type\n268\t        Map<String, Long> eventsByEntityType = new LinkedHashMap<>();\n269\t        List<Object[]> entityTypeCounts = auditLogRepository.countByEntityTypeForDateRange(tenantId, startDate, endDate);\n270\t        for (Object[] row : entityTypeCounts) {\n271\t            String entityType = (String) row[0];\n272\t            Long count = (Long) row[1];\n273\t            eventsByEntityType.put(entityType, count);\n274\t        }\n275\t\n276\t        // Top actors\n277\t        List<AuditStatisticsResponse.ActorActivity> topActors = new ArrayList<>();\n278\t        List<Object[]> actorCounts = auditLogRepository.countByActorForDateRange(tenantId, startDate, endDate);\n279\t        int limit = Math.min(10, actorCounts.size());\n280\t        for (int i = 0; i < limit; i++) {\n281\t            Object[] row = actorCounts.get(i);\n282\t            topActors.add(AuditStatisticsResponse.ActorActivity.builder()\n283\t                    .actorId((UUID) row[0])\n284\t                    .actorEmail((String) row[1])\n285\t                    .eventCount((Long) row[2])\n286\t                    .build());\n287\t        }\n288\t\n289\t        // Daily counts\n290\t        List<AuditStatisticsResponse.DailyCount> dailyCounts = new ArrayList<>();\n291\t        List<Object[]> dayCounts = auditLogRepository.countByDayForDateRange(tenantId, startDate, endDate);\n292\t        for (Object[] row : dayCounts) {\n293\t            java.sql.Date sqlDate = (java.sql.Date) row[0];\n294\t            Long count = (Long) row[1];\n295\t            dailyCounts.add(AuditStatisticsResponse.DailyCount.builder()\n296\t                    .date(sqlDate.toLocalDate())\n297\t                    .count(count)\n298\t                    .build());\n299\t        }\n300\t\n301\t        return AuditStatisticsResponse.builder()\n302\t                .totalEvents(totalEvents)\n303\t                .startDate(startDate)\n304\t                .endDate(endDate)\n305\t                .eventsByAction(eventsByAction)\n306\t                .eventsByEntityType(eventsByEntityType)\n307\t                .topActors(topActors)\n308\t                .dailyCounts(dailyCounts)\n309\t                .build();\n310\t    }\n311\t\n312\t    @Transactional(readOnly = true)\n313\t    public Map<String, Long> getAuditSummary() {\n314\t        UUID tenantId = TenantContext.getCurrentTenant();\n315\t        Map<String, Long> summary = new LinkedHashMap<>();\n316\t\n317\t        summary.put(\"totalEvents\", auditLogRepository.countByTenantId(tenantId));\n318\t\n319\t        // Last 24 hours\n320\t        LocalDateTime now = tenantTimeService.now(tenantId);\n321\t        LocalDateTime yesterday = now.minusDays(1);\n322\t        summary.put(\"eventsLast24Hours\", auditLogRepository.countByTenantIdAndDateRange(tenantId, yesterday, now));\n323\t\n324\t        // Last 7 days\n325\t        LocalDateTime lastWeek = now.minusDays(7);\n326\t        summary.put(\"eventsLast7Days\", auditLogRepository.countByTenantIdAndDateRange(tenantId, lastWeek, now));\n327\t\n328\t        // Last 30 days\n329\t        LocalDateTime lastMonth = now.minusDays(30);\n330\t        summary.put(\"eventsLast30Days\", auditLogRepository.countByTenantIdAndDateRange(tenantId, lastMonth, now));\n331\t\n332\t        return summary;\n333\t    }\n334\t\n335\t    @Transactional(readOnly = true)\n336\t    public List<String> getDistinctEntityTypes() {\n337\t        UUID tenantId = TenantContext.getCurrentTenant();\n338\t        // Return common entity types\n339\t        return Arrays.asList(\n340\t                \"USER\", \"EMPLOYEE\", \"DEPARTMENT\", \"LEAVE_REQUEST\", \"ATTENDANCE\",\n341\t                \"PAYROLL\", \"EXPENSE\", \"DOCUMENT\", \"ROLE\", \"PERMISSION\"\n342\t        );\n343\t    }\n344\t\n345\t    // ==================== Helper Methods ====================\n346\t\n347\t    private AuditLogResponse enrichResponse(AuditLog entity) {\n348\t        AuditLogResponse response = AuditLogResponse.fromEntity(entity);\n349\t\n350\t        // Enrich with actor name\n351\t        UUID tenantId = TenantContext.getCurrentTenant();\n352\t        if (entity.getActorId() != null) {\n353\t            employeeRepository.findByIdAndTenantId(entity.getActorId(), tenantId)\n354\t                    .ifPresent(emp -> response.setActorName(emp.getFirstName() + \" \" + emp.getLastName()));\n355\t        }\n356\t\n357\t        return response;\n358\t    }\n359\t\n360\t    private HttpServletRequest getHttpServletRequest() {\n361\t        try {\n362\t            ServletRequestAttributes attributes = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();\n363\t            return attributes != null ? attributes.getRequest() : null;\n364\t        } catch (Exception e) { // Intentional broad catch — service error boundary\n365\t            return null;\n366\t        }\n367\t    }\n368\t\n369\t    private String getClientIp(HttpServletRequest request) {\n370\t        String xForwardedFor = request.getHeader(\"X-Forwarded-For\");\n371\t        if (xForwardedFor != null && !xForwardedFor.isEmpty()) {\n372\t            return xForwardedFor.split(\",\")[0].trim();\n373\t        }\n374\t        String ip = request.getRemoteAddr();\n375\t        return ip != null && ip.length() <= 50 ? ip : (ip != null ? ip.substring(0, 50) : null);\n376\t    }\n377\t\n378\t    // ==================== Legacy Methods (Backward Compatibility) ====================\n379\t\n380\t    @Transactional(readOnly = true)\n381\t    public Page<AuditLog> getAuditLogs(int page, int size) {\n382\t        Pageable pageable = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, \"createdAt\"));\n383\t        return auditLogRepository.findAll(pageable);\n384\t    }\n385\t\n386\t    @Transactional(readOnly = true)\n387\t    public Page<AuditLog> getAuditLogsByEntityType(String entityType, int page, int size) {\n388\t        Pageable pageable = PageRequest.of(page, size);\n389\t        return auditLogRepository.findByEntityTypeOrderByCreatedAtDesc(entityType, pageable);\n390\t    }\n391\t\n392\t    @Transactional(readOnly = true)\n393\t    public Page<AuditLog> getAuditLogsByEntity(String entityType, UUID entityId, int page, int size) {\n394\t        Pageable pageable = PageRequest.of(page, size);\n395\t        return auditLogRepository.findByEntityTypeAndEntityIdOrderByCreatedAtDesc(entityType, entityId, pageable);\n396\t    }\n397\t\n398\t    @Transactional(readOnly = true)\n399\t    public Page<AuditLog> getAuditLogsByActor(UUID actorId, int page, int size) {\n400\t        Pageable pageable = PageRequest.of(page, size);\n401\t        return auditLogRepository.findByActorIdOrderByCreatedAtDesc(actorId, pageable);\n402\t    }\n403\t\n404\t    @Transactional(readOnly = true)\n405\t    public Page<AuditLog> getAuditLogsByAction(AuditAction action, int page, int size) {\n406\t        Pageable pageable = PageRequest.of(page, size);\n407\t        return auditLogRepository.findByActionOrderByCreatedAtDesc(action, pageable);\n408\t    }\n409\t\n410\t    @Transactional(readOnly = true)\n411\t    public Page<AuditLog> getAuditLogsByDateRange(LocalDateTime startDate, LocalDateTime endDate, int page, int size) {\n412\t        Pageable pageable = PageRequest.of(page, size);\n413\t        return auditLogRepository.findByDateRange(startDate, endDate, pageable);\n414\t    }\n415\t}\n416\t"}]},"parent_tool_use_id":"toolu_01JgAM9Ax18NS4WRFCdnZTFn","session_id":"61db98fd-c720-4414-89bd-2708d1298a20","uuid":"eec48c44-a94a-4111-9d25-bc4795744d8c","timestamp":"2026-06-11T19:26:26.465Z","subagent_type":"Explore","task_description":"Explore audit search endpoint+tests"}
